// ---------- storage ----------
async function renderReporteMensual(){
  const panel = document.getElementById("reporte-panel");
  panel.innerHTML = `<div class="empty-state">Generando reporte…</div>`;
  try{
    const now = new Date();
    const mesActual = now.getMonth(), anioActual = now.getFullYear();
    const nombreMes = MESES[mesActual] ? cap(MESES[mesActual]) : "";

    const [contratosRes, empleadosRes] = await Promise.all([
      window.storage.list("contrato:", false),
      window.storage.list(CATALOGS.empleados.prefix, false),
    ]);
    const contratos = await Promise.all(((contratosRes && contratosRes.keys) || []).map(async k => {
      try{ const r = await window.storage.get(k, false); return r && r.value ? JSON.parse(r.value) : {}; }catch(e){ return {}; }
    }));
    const empleados = await Promise.all(((empleadosRes && empleadosRes.keys) || []).map(async k => {
      try{ const r = await window.storage.get(k, false); return r && r.value ? JSON.parse(r.value) : {}; }catch(e){ return {}; }
    }));

    const esEsteMes = iso => {
      if (!iso) return false;
      const d = new Date(iso);
      return d.getMonth() === mesActual && d.getFullYear() === anioActual;
    };

    const contratosNuevos = contratos.filter(c => esEsteMes(c._createdAt));
    const contratosActualizados = contratos.filter(c => c._updatedAt && !esEsteMes(c._createdAt) && esEsteMes(c._updatedAt));
    const salidasEsteMes = empleados.filter(e => e.ARCHIVADO && esEsteMes(e.FECHA_ARCHIVADO ? new Date(e.FECHA_ARCHIVADO.split("/").reverse().join("-")).toISOString() : null));
    const empleadosActivos = empleados.filter(e => !e.ARCHIVADO);
    const handbooksPendientes = empleadosActivos.filter(e => !e.HANDBOOK_FIRMADO_FECHA);
    const vencenPronto = contratos.filter(d => estadoVencimiento(d));
    const salariosBajoMinimo = empleadosActivos.filter(e => {
      const n = Number(String(e.SALARIO_EMP||"").replace(/[^0-9.]/g,""));
      const ref = buscarSalarioMinimoPorDepartamento(e.DEPARTAMENTO_EMP);
      return ref && ref.salarioMin && n && n < ref.salarioMin;
    });

    const fila = (label, valor) => `<div style="display:flex; justify-content:space-between; padding:8px 0; border-bottom:1px solid var(--paper-line);">
      <span style="font-size:13px;">${label}</span><span style="font-weight:800; color:var(--navy-deep);">${valor}</span>
    </div>`;

    panel.innerHTML = `
      <div style="margin-bottom:12px;">
        <div style="font-size:18px; font-weight:800; color:var(--navy-deep);">📊 Reporte de RRHH — ${nombreMes} ${anioActual}</div>
        <div style="font-size:12px; color:var(--ink-soft);">Generado automáticamente con los datos guardados en este navegador.</div>
      </div>
      <div class="section-card"><div class="section-body">
        <div style="font-weight:700; margin-bottom:4px;">Movimiento del mes</div>
        ${fila("Contratos nuevos creados", contratosNuevos.length)}
        ${fila("Contratos actualizados", contratosActualizados.length)}
        ${fila("Salidas / archivados", salidasEsteMes.length)}
      </div></div>
      <div class="section-card" style="margin-top:10px;"><div class="section-body">
        <div style="font-weight:700; margin-bottom:4px;">Estado general</div>
        ${fila("Empleados activos", empleadosActivos.length)}
        ${fila("Contratos guardados en total", contratos.length)}
        ${fila("Handbooks pendientes de firma", handbooksPendientes.length)}
        ${fila("Contratos por vencer / vencidos", vencenPronto.length)}
        ${fila("Salarios bajo el mínimo MTSS", salariosBajoMinimo.length)}
      </div></div>
      ${handbooksPendientes.length ? `<div class="section-card" style="margin-top:10px; border-color:#D9A54A;"><div class="section-body">
        <div style="font-weight:700; color:#8a6d1f; margin-bottom:4px;">Pendientes de firmar Handbook</div>
        ${handbooksPendientes.map(e => `<div style="font-size:12.5px;">• ${escapeHtml(nombreCompletoEmpleado(e))}</div>`).join("")}
      </div></div>` : ""}
      ${salariosBajoMinimo.length ? `<div class="section-card" style="margin-top:10px; border-color:#B3261E;"><div class="section-body">
        <div style="font-weight:700; color:#B3261E; margin-bottom:4px;">Salarios bajo el mínimo legal</div>
        ${salariosBajoMinimo.map(e => `<div style="font-size:12.5px;">• ${escapeHtml(nombreCompletoEmpleado(e))} — ${escapeHtml(e.DEPARTAMENTO_EMP||"")}</div>`).join("")}
      </div></div>` : ""}
      <button class="btn gold" style="width:100%; margin-top:14px;" onclick="window.print()">⬇️ Descargar este reporte (PDF)</button>
    `;
  }catch(e){ panel.innerHTML = `<div class="empty-state">No se pudo generar el reporte.</div>`; }
}

function calcularVacaciones(){
  const meses = Number(document.getElementById("faq-meses-input").value || 0);
  const dias = Math.floor(meses / 50 * 15 * 100) / 100; // 2 semanas (15 días) por cada 50 semanas ≈ proporción por mes trabajado
  // more precise: Art.153 grants 1 day per full month worked once continuity exceeds 50 weeks; simplified linear estimate
  const diasSimple = Math.round((meses / 12) * 15 * 10) / 10;
  document.getElementById("faq-meses-resultado").textContent =
    `Aproximadamente ${diasSimple} día(s) de vacaciones proporcionales (referencia: 15 días por año completo, Art. 153 CT). Para el cálculo exacto de tu caso, confirma con Legal.`;
}

// ---------- payroll slip (colilla) importer ----------
let colillasResultadosCache = [];

function normalizarNombre(s){
  return (s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase()
    .split(/\s+/).filter(Boolean).sort().join(" ");
}

// El nombre del archivo es la única pista de moneda que trae la colilla — el
// texto de la boleta en sí es idéntico en colones y en dólares, solo cambia
// el monto. Sigue el patrón ya usado por el negocio: "... (colones).pdf" /
// "... (dólares).pdf". Si el nombre no dice nada, se asume colones (igual que
// siempre se hizo, antes de que existiera esta distinción).
function detectarMonedaArchivo(nombreArchivo){
  const n = (nombreArchivo || "").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
  if (/\b(dolar|dolares|usd)\b/.test(n)) return "USD";
  return "CRC";
}

// Cuando el nombre completo del empleado es largo, la plantilla de la colilla lo
// envuelve a una segunda línea (comparte fila con "Departamento" en el diseño,
// pero esa línea queda más abajo en el PDF). Como el lector de texto ordena por
// posición vertical, esa línea suelta con el resto del nombre termina apareciendo
// DESPUÉS de "Salario Mensual" en el texto extraído, y la regex principal (que no
// cruza líneas) la deja fuera — el nombre queda cortado (ej. "...DE LOS" sin
// "ANGELES"). Esto rompe el emparejado por nombre contra la ficha del empleado.
// Aquí se reconstruye: si justo antes de "Departamento" hay una línea suelta sin
// ":" (no es otro campo con etiqueta), es la continuación del nombre envuelto.
function completarNombreConLineaSuelta(chunk, m, nombre){
  const finMatch = m.index + m[0].length;
  const nlIdx = chunk.indexOf("\n", finMatch);
  if (nlIdx === -1) return nombre;
  const cont = chunk.slice(nlIdx + 1).match(/^([^\n:]{1,40})\n\s*Departamento/);
  return cont ? `${nombre} ${cont[1].trim()}`.replace(/\s+/g," ").trim() : nombre;
}

// onColillasPdfSelected marca el inicio del texto de cada archivo con
// "[[MONEDA:CRC]]" o "[[MONEDA:USD]]" antes de concatenarlo — así, aunque se
// suban varios PDF a la vez (uno en colones y otro en dólares), cada registro
// sabe en qué moneda venía su boleta. Si se pega texto a mano no hay marca,
// así que todo se trata como colones, como siempre.
function parseColillas(text){
  const empleados = [];
  const partes = text.split(/\[\[MONEDA:(CRC|USD)\]\]/);
  let monedaActual = "CRC";
  for (let i = 0; i < partes.length; i++){
    if (i % 2 === 1){ monedaActual = partes[i]; continue; }
    const chunks = partes[i].split(/Empleado:\s*/).slice(1);
    chunks.forEach(chunk => {
      // name is capped to a reasonable length as a safety net — a genuine full name
      // never runs 60+ characters, so this stops a broken line-join from swallowing
      // the rest of the payslip into the name/occupation fields.
      const m = chunk.match(/^(\d+)\s+([^\n]{1,60}?)\s+Salario Mensual:\s*([\d,]+\.\d+)/s);
      if (!m) return;
      const numero = m[1];
      const nombre = completarNombreConLineaSuelta(chunk, m, m[2].replace(/\s+/g," ").trim());
      const salario = parseFloat(m[3].replace(/,/g,""));
      const deptMatch = chunk.match(/Departamento\s*:\s*([^\n]{1,60})/);
      const ocupMatch = chunk.match(/Ocupaci[oó]n:\s*([^\n]{1,60})/);
      const cedulaMatch = chunk.match(/[Cc]édula\D{0,10}(\d[\d-]{7,10}\d)/);
      empleados.push({
        numero, nombre, salario: isNaN(salario) ? 0 : salario,
        departamento: deptMatch ? deptMatch[1].trim() : "",
        ocupacion: ocupMatch ? ocupMatch[1].trim() : "",
        cedula: cedulaMatch ? cedulaMatch[1].trim() : "",
        moneda: monedaActual,
      });
    });
  }
  return empleados;
}

function levenshtein(a, b){
  const m = a.length, n = b.length;
  const dp = Array.from({length: m+1}, () => new Array(n+1).fill(0));
  for (let i=0;i<=m;i++) dp[i][0]=i;
  for (let j=0;j<=n;j++) dp[0][j]=j;
  for (let i=1;i<=m;i++)
    for (let j=1;j<=n;j++)
      dp[i][j] = a[i-1]===b[j-1] ? dp[i-1][j-1] : 1+Math.min(dp[i-1][j-1],dp[i-1][j],dp[i][j-1]);
  return dp[m][n];
}

// finds an employee whose name is nearly identical (allows small typos) when no exact match exists
function buscarCoincidenciaDifusa(nombreColilla, empleadosDB){
  const wordsColilla = normalizarNombre(nombreColilla).split(" ").filter(Boolean);
  let mejor = null, mejorScore = Infinity;
  empleadosDB.forEach(e => {
    const wordsDB = normalizarNombre(nombreCompletoEmpleado(e)).split(" ").filter(Boolean);
    if (wordsDB.length !== wordsColilla.length) return; // only compare names with the same word count, for safety
    let totalDist = 0;
    for (let i=0;i<wordsColilla.length;i++) totalDist += levenshtein(wordsColilla[i], wordsDB[i]);
    if (totalDist < mejorScore){ mejorScore = totalDist; mejor = e; }
  });
  // accept only very close matches (at most ~2 characters different across the whole name) to avoid false positives
  return (mejor && mejorScore > 0 && mejorScore <= 2) ? mejor : null;
}

// Carga el catálogo de empleados de la propiedad activa. Factorizado porque lo
// usan tanto la actualización de salarios como el archivado individual de colillas.
async function cargarEmpleadosDB(){
  const res = await window.storage.list(CATALOGS.empleados.prefix, false);
  const keys = (res && res.keys) || [];
  return Promise.all(keys.map(async k => {
    const r = await window.storage.get(k, false);
    const v = r && r.value ? JSON.parse(r.value) : {};
    return { key: k.replace(CATALOGS.empleados.prefix,""), ...v };
  }));
}

// Orden alfabético "oficial" del sistema para listas de empleados: por las
// primeras 2 letras del apellido (campo APELLIDOS_EMP). Se usan solo 2
// letras a propósito (más simple de capturar que el apellido completo) —
// empleados que compartan esas 2 letras quedan sin un orden fino entre
// ellos. Si un empleado todavía no tiene apellido capturado (fichas
// creadas antes de que existiera el campo, cuando NOMBRE_EMP todavía
// guardaba el nombre completo), cae de vuelta a NOMBRE_EMP para no
// dejarlo fuera de orden mientras se actualiza su ficha.
function apellidoParaOrden(emp){
  const base = (emp && (emp.APELLIDOS_EMP || emp.NOMBRE_EMP)) || "";
  return base.trim().slice(0, 2);
}
function compararPorApellido(a, b){
  return apellidoParaOrden(a).localeCompare(apellidoParaOrden(b), "es");
}

// Nombre legal completo de un empleado: NOMBRE_EMP (solo el nombre de
// pila, ej. "ISAAC") + APELLIDOS_EMP (ej. "QUIROS MORA"). Esta es la única
// función que debe usarse para MOSTRAR el nombre de un empleado — en
// contratos, cartas, reportes, el calendario, etc. Fallback: si
// APELLIDOS_EMP todavía no se capturó (fichas creadas antes de que
// existiera el campo separado), NOMBRE_EMP en esos registros viejos SÍ
// tiene el nombre completo, así que devolverlo solo no rompe nada.
function nombreCompletoEmpleado(emp){
  if (!emp) return "";
  const nombre = (emp.NOMBRE_EMP || "").trim();
  const apellidos = (emp.APELLIDOS_EMP || "").trim();
  return apellidos ? `${nombre} ${apellidos}`.trim() : nombre;
}

// Heurística para partir un nombre completo en texto libre (ej. el que
// trae una colilla de pago externa) en nombre de pila + apellidos: se
// asume el formato más común en Costa Rica, "Nombre(s) Apellido1
// Apellido2" — las últimas 2 palabras son los apellidos, el resto es el
// nombre. Con exactamente 2 palabras se parte 1 y 1; con 1 sola palabra,
// todo queda como nombre (no hay nada que partir). Es una heurística, no
// una certeza — puede fallar con apellidos de una sola palabra o nombres
// compuestos; por eso solo se usa para la corrección automática de un
// typo ya detectado por coincidencia difusa contra un empleado existente
// (ver emparejarRegistroColilla), nunca para adivinar de cero.
function dividirNombreCompleto(nombreCompleto){
  const palabras = String(nombreCompleto || "").trim().split(/\s+/).filter(Boolean);
  if (palabras.length <= 1) return { nombre: palabras.join(" "), apellidos: "" };
  if (palabras.length === 2) return { nombre: palabras[0], apellidos: palabras[1] };
  return { nombre: palabras.slice(0, -2).join(" "), apellidos: palabras.slice(-2).join(" ") };
}

// Filtro de búsqueda para un <select> largo de empleados: oculta (no
// elimina) las <option> cuyo texto no coincida, así el value que termine
// eligiéndose sigue siendo la key real del empleado — la búsqueda es solo
// para encontrarlo más rápido en la lista, nunca cambia qué se guarda.
function filtrarSelectEmpleados(inputBusqueda, selectId){
  const termino = inputBusqueda.value.toLowerCase().trim();
  const select = document.getElementById(selectId);
  if (!select) return;
  Array.from(select.options).forEach(opt => {
    if (!opt.value) return; // "— Elegí —" siempre visible
    opt.hidden = !(!termino || opt.textContent.toLowerCase().includes(termino));
  });
}

function construirIndicesEmpleados(empleadosDB){
  const porNumero = {}, porCedula = {}, porNombre = {};
  empleadosDB.forEach(e => {
    if (e.NUMERO_EMPLEADO) porNumero[String(e.NUMERO_EMPLEADO).trim().replace(/^0+/,"")] = e;
    if (e.IDENTIFICACION_EMP) porCedula[e.IDENTIFICACION_EMP.replace(/\D/g,"")] = e;
    porNombre[normalizarNombre(nombreCompletoEmpleado(e))] = e;
  });
  return { porNumero, porCedula, porNombre };
}

// Mismo criterio de emparejado (número → cédula → nombre exacto → nombre con
// pequeños errores de tipeo) usado tanto para actualizar salarios como para
// archivar la colilla individual de cada quien.
function emparejarRegistroColilla(p, indices, empleadosDB){
  let match = null, nombreCorregido = null, matchedBy = null;
  if (p.numero && indices.porNumero[p.numero.replace(/^0+/,"")]){
    match = indices.porNumero[p.numero.replace(/^0+/,"")];
    matchedBy = "número de empleado";
  }
  if (!match && p.cedula && indices.porCedula[p.cedula.replace(/\D/g,"")]){
    match = indices.porCedula[p.cedula.replace(/\D/g,"")];
    matchedBy = "cédula";
  }
  if (!match){
    match = indices.porNombre[normalizarNombre(p.nombre)] || null;
    if (match) matchedBy = "nombre";
  }
  if (!match){
    const fuzzy = buscarCoincidenciaDifusa(p.nombre, empleadosDB);
    if (fuzzy){
      match = fuzzy;
      nombreCorregido = { anterior: nombreCompletoEmpleado(fuzzy), nuevo: p.nombre };
      matchedBy = "nombre (con corrección)";
    }
  }
  return { match, nombreCorregido, matchedBy };
}

async function procesarColillas(){
  const text = document.getElementById("colillas-textarea").value;
  if (!text.trim()){ statusMsg("Pega primero el texto de la(s) colilla(s).", false); return; }
  const parsed = parseColillas(text);
  if (parsed.length === 0){
    statusMsg("No se reconoció ningún registro con el formato esperado (\"Empleado: N Nombre Salario Mensual: monto\"). Si el PDF es de otro sistema de planillas o cambió de formato, revisa el texto extraído abajo y avisa para ajustar el lector.", false);
    document.getElementById("colillas-resultados").innerHTML = `<div class="section-card" style="margin-top:10px; border-color:#B3261E;"><div class="section-body">
      <div style="font-weight:700; color:#B3261E; margin-bottom:6px;">⚠️ No se reconoció ningún empleado en este texto</div>
      <div style="font-size:12px; color:var(--ink-soft);">El texto se leyó (${text.length} caracteres) pero no calza con el formato esperado. Revísalo en el cuadro de arriba — si es de un sistema de planillas distinto, compártelo para ajustar el lector.</div>
    </div></div>`;
    return;
  }

  let empleadosDB;
  try{
    empleadosDB = await cargarEmpleadosDB();
  }catch(e){
    statusMsg("No se pudo cargar la lista de empleados para comparar: " + e.message, false);
    return;
  }
  const indices = construirIndicesEmpleados(empleadosDB);

  colillasResultadosCache = parsed.map(p => {
    const { match, nombreCorregido, matchedBy } = emparejarRegistroColilla(p, indices, empleadosDB);
    const puestoCoincide = match ? (normalizarNombre(match.DEPARTAMENTO_EMP) === normalizarNombre(p.ocupacion)) : null;
    // Un salario en colones que cae a menos de un tercio del que ya tenía
    // guardado (o que se triplica) casi nunca es un cambio real dentro de la
    // misma moneda — el caso típico es una colilla en dólares sin marcar como
    // tal. Solo se evalúa para registros en colones: los de USD van a su
    // propio campo (SALARIO_USD_EMP) y nunca se comparan contra el de colones.
    let salarioSospechoso = false;
    if (p.moneda !== "USD" && match && match.SALARIO_EMP){
      const anterior = Number(String(match.SALARIO_EMP).replace(/[^0-9.]/g,""));
      if (anterior > 0 && (p.salario < anterior * 0.3 || p.salario > anterior * 3)) salarioSospechoso = true;
    }
    return Object.assign({}, p, { match, puestoCoincide, nombreCorregido, matchedBy, salarioSospechoso });
  });
  renderColillasPreview();
}

function renderColillasPreview(){
  const wrap = document.getElementById("colillas-resultados");
  const todosEncontrados = colillasResultadosCache.filter(r => r.match);
  const usd = todosEncontrados.filter(r => r.moneda === "USD");
  const resto = todosEncontrados.filter(r => r.moneda !== "USD");
  const encontrados = resto.filter(r => !r.salarioSospechoso);
  const sospechosos = resto.filter(r => r.salarioSospechoso);
  const noEncontrados = colillasResultadosCache.filter(r => !r.match);

  let html = `<div class="section-card" style="border-color:var(--leaf); margin-top:12px;"><div class="section-body">
    <div style="font-weight:700; margin-bottom:4px;">Resumen</div>
    <div style="font-size:12.5px;">${colillasResultadosCache.length} registros leídos en la colilla · <b style="color:var(--leaf);">${encontrados.length} coinciden</b> con tu lista de empleados · <b style="color:#B3261E;">${noEncontrados.length} sin coincidencia</b>${sospechosos.length ? ` · <b style="color:#B3261E;">${sospechosos.length} con salario sospechoso</b>` : ""}${usd.length ? ` · <b style="color:var(--navy-deep);">${usd.length} en dólares</b>` : ""}</div>
  </div></div>`;

  if (usd.length){
    html += `<div class="section-card" style="margin-top:10px; border-color:var(--navy-deep);"><div class="section-body">
      <div style="font-weight:700; margin-bottom:6px;">💵 Se actualizará el salario en dólares de:</div>
      <div style="font-size:11.5px; color:var(--ink-soft); margin-bottom:8px;">Este PDF se detectó como colilla en dólares por su nombre de archivo. El monto se guarda aparte, en "Salario mensual en dólares" — nunca toca el salario en colones de la ficha.</div>
      ${usd.map(r => {
        const anteriorUsd = r.match.SALARIO_USD_EMP;
        const cambia = String(anteriorUsd||"").trim() !== String(r.salario).trim();
        return `<div style="font-size:12px; padding:5px 0; border-bottom:1px solid var(--paper-line);">
          <b>${escapeHtml(nombreCompletoEmpleado(r.match))}</b> — № ${escapeHtml(r.numero)} <span style="color:var(--ink-soft);">(emparejado por ${escapeHtml(r.matchedBy || "nombre")})</span><br>
          ${r.nombreCorregido ? `<span style="color:#8a6d1f;">✏️ Nombre corregido automáticamente: "${escapeHtml(r.nombreCorregido.anterior)}" → "${escapeHtml(r.nombreCorregido.nuevo)}"</span><br>` : ""}
          Salario en dólares: ${anteriorUsd ? "$"+Number(anteriorUsd).toLocaleString("en-US") : "—"} → <b style="color:${cambia?'var(--navy-deep)':'var(--ink-soft)'};">$${r.salario.toLocaleString("en-US")}</b>
          ${r.puestoCoincide === false ? `<br><span style="color:#8a6d1f;">⚠️ Puesto distinto — catálogo: "${escapeHtml(r.match.DEPARTAMENTO_EMP||"—")}" / colilla: "${escapeHtml(r.ocupacion)}"</span>` : ""}
        </div>`;
      }).join("")}
      <button class="btn primary" style="width:100%; margin-top:10px;" onclick="aplicarColillasUSD()">💵 Aplicar ${usd.length} actualización(es) en dólares</button>
    </div></div>`;
  }

  if (sospechosos.length){
    html += `<div class="section-card" style="margin-top:10px; border-color:#B3261E;"><div class="section-body">
      <div style="font-weight:700; color:#B3261E; margin-bottom:6px;">🚫 Salario muy distinto al guardado — no se aplica solo, confírmalo uno por uno</div>
      <div style="font-size:11.5px; color:var(--ink-soft); margin-bottom:8px;">El caso típico es una colilla en dólares que se leyó como si fueran colones. Verifica el monto real antes de confirmar — si de verdad es correcto, "Aplicar de todas formas" lo guarda.</div>
      ${sospechosos.map((r, i) => {
        const idx = colillasResultadosCache.indexOf(r);
        return `<div style="font-size:12px; padding:6px 0; border-bottom:1px solid var(--paper-line);">
          <b>${escapeHtml(nombreCompletoEmpleado(r.match))}</b> — № ${escapeHtml(r.numero)}<br>
          Salario guardado: ₡${Number(r.match.SALARIO_EMP).toLocaleString("es-CR")} → colilla dice: <b style="color:#B3261E;">${r.salario.toLocaleString("es-CR")}</b> (¿colones o dólares?)
          <div style="margin-top:4px;">
            <button class="btn" style="padding:4px 10px; font-size:11px;" onclick="aplicarColillaIndividual(${idx})">Aplicar de todas formas</button>
            <button class="btn" style="padding:4px 10px; font-size:11px;" onclick="colillasResultadosCache[${idx}].match=null; renderColillasPreview();">Ignorar esta fila</button>
          </div>
        </div>`;
      }).join("")}
    </div></div>`;
  }

  if (encontrados.length){
    const corregidos = encontrados.filter(r => r.nombreCorregido);
    html += `<div class="section-card" style="margin-top:10px;"><div class="section-body">
      <div style="font-weight:700; margin-bottom:6px;">✅ Se actualizará el salario de:</div>
      ${encontrados.map(r => {
        const cambia = String(r.match.SALARIO_EMP||"").trim() !== String(r.salario).trim();
        return `<div style="font-size:12px; padding:5px 0; border-bottom:1px solid var(--paper-line);">
          <b>${escapeHtml(nombreCompletoEmpleado(r.match))}</b> — № ${escapeHtml(r.numero)} <span style="color:var(--ink-soft);">(emparejado por ${escapeHtml(r.matchedBy || "nombre")})</span><br>
          ${r.nombreCorregido ? `<span style="color:#8a6d1f;">✏️ Nombre corregido automáticamente: "${escapeHtml(r.nombreCorregido.anterior)}" → "${escapeHtml(r.nombreCorregido.nuevo)}"</span><br>` : ""}
          Salario: ${r.match.SALARIO_EMP ? "₡"+Number(r.match.SALARIO_EMP).toLocaleString("es-CR") : "—"} → <b style="color:${cambia?'var(--navy-deep)':'var(--ink-soft)'};">₡${r.salario.toLocaleString("es-CR")}</b>
          ${r.puestoCoincide === false ? `<br><span style="color:#8a6d1f;">⚠️ Puesto distinto — catálogo: "${escapeHtml(r.match.DEPARTAMENTO_EMP||"—")}" / colilla: "${escapeHtml(r.ocupacion)}"</span>` : ""}
        </div>`;
      }).join("")}
      <button class="btn primary" style="width:100%; margin-top:10px;" onclick="aplicarColillas()">✅ Aplicar ${encontrados.length} actualización(es)${corregidos.length ? " (incluye " + corregidos.length + " corrección(es) de nombre)" : ""}</button>
    </div></div>`;
  }

  if (noEncontrados.length){
    html += `<div class="section-card" style="margin-top:10px; border-color:#D9A54A;"><div class="section-body">
      <div style="font-weight:700; color:#8a6d1f; margin-bottom:6px;">⚠️ Sin coincidencia en tu lista de empleados (revisar nombre manualmente):</div>
      ${noEncontrados.map(r => `<div style="font-size:12px; padding:3px 0;">• ${escapeHtml(r.nombre)} — № ${escapeHtml(r.numero)} — ₡${r.salario.toLocaleString("es-CR")} (${escapeHtml(r.ocupacion)})</div>`).join("")}
    </div></div>`;
  }

  wrap.innerHTML = html;
}

// Aplica UNA sola fila de la lista de "salario sospechoso", tras confirmarla
// a mano — usa la misma lógica que aplicarColillas() pero para un solo registro.
async function aplicarColillaIndividual(idx){
  const r = colillasResultadosCache[idx];
  if (!r || !r.match) return;
  const fullKey = CATALOGS.empleados.prefix + r.match.key;
  const salarioAnterior = r.match.SALARIO_EMP || "—";
  r.match.SALARIO_EMP = String(r.salario);
  if (!r.match.NUMERO_EMPLEADO) r.match.NUMERO_EMPLEADO = r.numero;
  if (r.nombreCorregido){
    const partido = dividirNombreCompleto(r.nombreCorregido.nuevo);
    r.match.NOMBRE_EMP = partido.nombre;
    r.match.APELLIDOS_EMP = partido.apellidos;
  }
  await window.storage.set(fullKey, JSON.stringify(r.match), false);
  await agregarBitacora(r.match.key, `Salario actualizado desde colilla de pago (confirmado a mano tras aviso de monto sospechoso): ${salarioAnterior} → ${r.salario} (№ empleado ${r.numero}).`);
  statusMsg(`Salario de ${nombreCompletoEmpleado(r.match)} actualizado.`);
  colillasResultadosCache[idx] = Object.assign({}, r, { match: null }); // ya aplicado, se quita de la lista de pendientes
  renderColillasPreview();
}

// Aplica en bloque los registros marcados como dólares (por el nombre del
// archivo) — escribe en SALARIO_USD_EMP, nunca en SALARIO_EMP (colones).
async function aplicarColillasUSD(){
  const usd = colillasResultadosCache.filter(r => r.match && r.moneda === "USD");
  let count = 0;
  for (const r of usd){
    const fullKey = CATALOGS.empleados.prefix + r.match.key;
    const anteriorUsd = r.match.SALARIO_USD_EMP || "—";
    r.match.SALARIO_USD_EMP = String(r.salario);
    r.match.MONEDA_SALARIO_EMP = "USD";
    // Igual que la entrada manual (onSalarioUsdEmpInput): guarda el bruto en
    // letras y el neto aproximado (–10.83% CCSS), número y letras, sin tocar
    // nunca el salario en colones de la ficha.
    r.match.SALARIO_USD_EMP_LETRAS = salarioEnLetras(r.salario, "dólares", "es");
    const netoUsd = r.salario * (1 - DEDUCCION_CCSS);
    r.match.SALARIO_USD_EMP_NETO = netoUsd.toFixed(2);
    r.match.SALARIO_USD_EMP_NETO_LETRAS = salarioEnLetras(netoUsd, "dólares", "es");
    if (!r.match.NUMERO_EMPLEADO) r.match.NUMERO_EMPLEADO = r.numero;
    if (r.nombreCorregido){
      const partido = dividirNombreCompleto(r.nombreCorregido.nuevo);
      r.match.NOMBRE_EMP = partido.nombre;
      r.match.APELLIDOS_EMP = partido.apellidos;
    }
    await window.storage.set(fullKey, JSON.stringify(r.match), false);
    if (r.nombreCorregido){
      await agregarBitacora(r.match.key, `Nombre corregido automáticamente desde colilla: "${r.nombreCorregido.anterior}" → "${r.nombreCorregido.nuevo}".`);
    }
    if (String(anteriorUsd) !== String(r.salario)){
      await agregarBitacora(r.match.key, `Salario en dólares actualizado desde colilla de pago: ${anteriorUsd} → ${r.salario} (№ empleado ${r.numero}).`);
    }
    count++;
  }
  statusMsg(`Actualizado el salario en dólares de ${count} empleado(s).`);
  colillasResultadosCache = colillasResultadosCache.map(r => (r.match && r.moneda === "USD") ? Object.assign({}, r, { match: null }) : r);
  renderColillasPreview();
}

async function aplicarColillas(){
  // Los de salario sospechoso, y los de dólares (que van por su propio botón
  // "Aplicar ... en dólares" arriba), quedan fuera del botón masivo en colones.
  const encontrados = colillasResultadosCache.filter(r => r.match && !r.salarioSospechoso && r.moneda !== "USD");
  let count = 0;
  const numerosSospechosos = [];
  for (const r of encontrados){
    const fullKey = CATALOGS.empleados.prefix + r.match.key;
    const salarioAnterior = r.match.SALARIO_EMP || "—";
    r.match.SALARIO_EMP = String(r.salario);
    // El número de empleado solo se GRABA la primera vez (cuando el registro
    // todavía no tenía uno). Si ya tenía un número distinto guardado, NO se
    // pisa en silencio — el emparejado por número tiene prioridad sobre el de
    // nombre en la próxima subida, así que sobrescribirlo sin avisar puede
    // pegarle el número (y de ahí en adelante el salario) de una persona a la
    // ficha de otra, para siempre, si alguna vez un nombre parecido empareja mal.
    const numeroAnterior = r.match.NUMERO_EMPLEADO ? String(r.match.NUMERO_EMPLEADO).replace(/^0+/,"") : "";
    const numeroNuevo = String(r.numero).replace(/^0+/,"");
    if (!numeroAnterior){
      r.match.NUMERO_EMPLEADO = r.numero;
    } else if (numeroAnterior !== numeroNuevo){
      numerosSospechosos.push(`${nombreCompletoEmpleado(r.match)}: tenía № ${r.match.NUMERO_EMPLEADO} guardado, la colilla trae № ${r.numero} — no se cambió, revísalo a mano.`);
    }
    if (r.nombreCorregido){
      const partido = dividirNombreCompleto(r.nombreCorregido.nuevo);
      r.match.NOMBRE_EMP = partido.nombre;
      r.match.APELLIDOS_EMP = partido.apellidos;
    }
    await window.storage.set(fullKey, JSON.stringify(r.match), false);
    if (r.nombreCorregido){
      await agregarBitacora(r.match.key, `Nombre corregido automáticamente desde colilla: "${r.nombreCorregido.anterior}" → "${r.nombreCorregido.nuevo}".`);
    }
    if (String(salarioAnterior) !== String(r.salario)){
      await agregarBitacora(r.match.key, `Salario actualizado desde colilla de pago: ${salarioAnterior} → ${r.salario} (№ empleado ${r.numero}).`);
    }
    count++;
  }
  const fechaHoy = fmtFecha(new Date().toISOString());
  await window.storage.set("colillas-ultima-actualizacion", fechaHoy + " (" + count + " empleado(s))", false);
  document.getElementById("colillas-pdf-status").innerHTML = `<span style="color:var(--leaf); font-weight:700;">✅ Aplicado y guardado — listo para la próxima quincena. Puedes subir otro PDF cuando quieras.</span>` +
    (numerosSospechosos.length ? `<div style="color:#B3261E; margin-top:6px;">⚠️ ${numerosSospechosos.length} caso(s) con número de empleado distinto al ya guardado — no se tocaron, revísalos:<br>${numerosSospechosos.map(escapeHtml).join("<br>")}</div>` : "");
  statusMsg(`Actualizados ${count} empleado(s) desde la colilla de pago.`);
  document.getElementById("colillas-textarea").value = "";
  document.getElementById("colillas-resultados").innerHTML = "";
  colillasResultadosCache = [];
}

async function renderColillasImporter(){
  const panel = document.getElementById("colillas-panel");
  let ultimaActualizacion = "";
  try{
    const r = await window.storage.get("colillas-ultima-actualizacion", false);
    if (r && r.value) ultimaActualizacion = r.value;
  }catch(e){ /* never run before */ }
  panel.innerHTML = `
    <div style="margin-bottom:12px;">
      <div style="font-size:18px; font-weight:800; color:var(--navy-deep);">🧾 Importación de colillas de pago</div>
      <div style="font-size:12px; color:var(--ink-soft);">Sube el/los PDF con las colillas de pago (por ejemplo, uno en colones y otro en dólares — puedes elegir ambos a la vez). El sistema las reparte automáticamente, empareja por número de empleado, cédula o nombre, corrige nombres con errores de tipeo, y actualiza el salario de cada quien.</div>
      ${ultimaActualizacion ? `<div style="font-size:11px; color:var(--leaf); margin-top:6px; font-weight:600;">✅ Última actualización aplicada: ${escapeHtml(ultimaActualizacion)}</div>` : ""}
    </div>
    <button class="btn primary" style="width:100%; margin-bottom:8px;" onclick="document.getElementById('colillas-pdf-input').click()">📄 Subir PDF(s) de colillas</button>
    <input type="file" id="colillas-pdf-input" accept=".pdf" multiple style="display:none;" onchange="onColillasPdfSelected(this)">
    <div id="colillas-pdf-status" style="font-size:11.5px; color:var(--ink-soft); margin-bottom:10px;"></div>
    <div style="display:flex; gap:8px; margin-bottom:10px;">
      <button class="btn" style="flex:1;" onclick="mostrarModalColillasArchivadas()">📋 Ver colillas archivadas</button>
      <button class="btn" style="flex:1;" onclick="mostrarModalColillasFaltantes()">⚠️ Ver faltantes</button>
    </div>
    <details style="margin-bottom:10px;">
      <summary style="font-size:11.5px; color:var(--ink-soft); cursor:pointer;">¿No tienes el PDF a mano? Pega el texto manualmente</summary>
      <div class="field" style="margin-top:8px;">
        <textarea id="colillas-textarea" style="min-height:140px;" placeholder="Pega aquí el texto completo de la(s) colilla(s) de pago…"></textarea>
      </div>
      <button class="btn" style="width:100%;" onclick="procesarColillas()">🔍 Procesar texto pegado</button>
    </details>
    <div id="colillas-resultados"></div>
  `;
}

// PDF text fragments don't always come in left-to-right reading order internally —
// group them into visual lines by vertical (Y) position, then sort each line by
// horizontal (X) position so the words come out in the order they're actually shown.
// Factorizado de extraerTextoPDF para poder leer una sola página a la vez (lo
// necesita el archivado individual de colillas, página por página).
function textoDePagina(content){
  const lineas = [];
  content.items.forEach(item => {
    if (!item.str || !item.str.trim()) return;
    const x = item.transform ? item.transform[4] : 0;
    const y = item.transform ? item.transform[5] : 0;
    let linea = lineas.find(l => Math.abs(l.y - y) <= 2);
    if (!linea){ linea = { y, items: [] }; lineas.push(linea); }
    linea.items.push({ x, str: item.str });
  });
  lineas.sort((a, b) => b.y - a.y); // PDF Y grows upward, so higher Y = higher on the page
  return lineas.map(l => {
    l.items.sort((a, b) => a.x - b.x);
    return l.items.map(it => it.str).join(" ");
  }).join("\n");
}

async function extraerTextoPDF(file){
  if (typeof pdfjsLib === "undefined"){
    throw new Error("El lector de PDF necesita conexión a internet la primera vez que se usa en este navegador.");
  }
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;
  let texto = "";
  for (let i = 1; i <= pdf.numPages; i++){
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    texto += textoDePagina(content) + "\n\n";
  }
  return texto;
}

// Igual que parseColillas, pero para el texto de UNA sola página (una colilla),
// y agrega el rango de fechas del período — se usa para archivar cada colilla
// bajo su empleado, con nombre de archivo que diga a qué quincena pertenece.
function parseColillaConPeriodo(texto){
  const chunks = texto.split(/Empleado:\s*/).slice(1);
  if (!chunks.length) return null;
  const chunk = chunks[0];
  const m = chunk.match(/^(\d+)\s+([^\n]{1,60}?)\s+Salario Mensual:\s*([\d,]+\.\d+)(?:\s+(\d{2}\/\d{2}\/\d{4})\s+Al\s*:\s*(\d{2}\/\d{2}\/\d{4}))?/s);
  if (!m) return null;
  const numero = m[1];
  const nombre = completarNombreConLineaSuelta(chunk, m, m[2].replace(/\s+/g," ").trim());
  const salario = parseFloat(m[3].replace(/,/g,""));
  const cedulaMatch = chunk.match(/[Cc]édula\D{0,10}(\d[\d-]{7,10}\d)/);
  return {
    numero, nombre, salario: isNaN(salario) ? 0 : salario,
    periodoInicio: m[4] || "", periodoFin: m[5] || "",
    cedula: cedulaMatch ? cedulaMatch[1].trim() : "",
  };
}

// Identifica una colilla archivada por empleado (cédula, o nombre si no tiene
// cédula capturada) + inicio de período — dos colillas con esa misma clave
// son "la misma quincena de la misma persona", sin importar si el PDF subido
// es byte-por-byte idéntico o solo corresponde al mismo período.
function claveColillaArchivada(cedula, nombreCompleto, periodoInicio){
  return (cedula || normalizarNombre(nombreCompleto)) + "|" + (periodoInicio || "");
}

// Trae las colillas ya archivadas de la propiedad y arma el set de claves
// para detectar duplicados antes de volver a guardar una. periodoInicio no se
// guarda en su propia columna — se recupera del nombre de archivo, que
// siempre termina en "_DD-MM-YYYY.pdf" (ver archivarColillasPDF). Las
// anuladas no cuentan como duplicado: si alguien anuló una colilla, sí debe
// poder archivarse una nueva para ese mismo período.
async function cargarClavesColillasArchivadas(){
  const docs = (await window.sdgApi.documentos({ tipo: "colilla_pago", limite: 5000 })) || [];
  const claves = new Set();
  docs.forEach(d => {
    if (d.anulado_en) return;
    const m = String(d.nombre_archivo || "").match(/_(\d{2})-(\d{2})-(\d{4})\.pdf$/i);
    const periodoInicio = m ? `${m[1]}/${m[2]}/${m[3]}` : "";
    claves.add(claveColillaArchivada(d.empleado_cedula, d.empleado_nombre, periodoInicio));
  });
  return claves;
}

// Lee un PDF de colillas página por página (cada página = una colilla), recorta
// la página de cada empleado que logre emparejar con el catálogo de Empleados
// como su propio PDF de una hoja, y la archiva en documentos_emitidos — igual
// que ya se archivan los contratos y cartas, solo con tipo "colilla_pago".
// La página del PDF original NUNCA se modifica, solo se copia.
// clavesYaArchivadas es compartido entre todos los archivos de una misma
// subida (ver onColillasPdfSelected), así que también detecta duplicados
// dentro del mismo lote, no solo contra lo que ya estaba guardado antes.
async function archivarColillasPDF(file, clavesYaArchivadas){
  if (typeof pdfjsLib === "undefined" || typeof PDFLib === "undefined"){
    throw new Error("El lector/escritor de PDF no está disponible en este navegador.");
  }
  const bufLectura = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: bufLectura }).promise;
  const registros = [];
  for (let i = 1; i <= pdf.numPages; i++){
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    const parsed = parseColillaConPeriodo(textoDePagina(content));
    if (parsed) registros.push(Object.assign({ pageIndex: i - 1 }, parsed));
  }
  if (!registros.length) return { archivados: 0, duplicados: 0, sinCoincidencia: [], total: 0 };

  const empleadosDB = await cargarEmpleadosDB();
  const indices = construirIndicesEmpleados(empleadosDB);
  if (!clavesYaArchivadas) clavesYaArchivadas = await cargarClavesColillasArchivadas();

  const bufEscritura = await file.arrayBuffer(); // copia aparte: pdf.js puede dejar inservible el buffer que ya usó
  const { PDFDocument } = PDFLib;
  const srcDoc = await PDFDocument.load(bufEscritura);

  let archivados = 0, duplicados = 0;
  const sinCoincidencia = [];
  for (const reg of registros){
    const { match } = emparejarRegistroColilla(reg, indices, empleadosDB);
    if (!match){ sinCoincidencia.push(reg); continue; }

    const clave = claveColillaArchivada(match.IDENTIFICACION_EMP, nombreCompletoEmpleado(match), reg.periodoInicio);
    if (clavesYaArchivadas.has(clave)){ duplicados++; continue; }

    const nuevoDoc = await PDFDocument.create();
    const [copiada] = await nuevoDoc.copyPages(srcDoc, [reg.pageIndex]);
    nuevoDoc.addPage(copiada);
    const bytes = await nuevoDoc.save();
    const blob = new Blob([bytes], { type: "application/pdf" });

    const periodoTxt = (reg.periodoInicio && reg.periodoFin) ? (reg.periodoInicio + " al " + reg.periodoFin) : "";
    try{
      await window.sdgApi.congelarDocumento(blob, {
        tipo: "colilla_pago",
        titulo: "Colilla de pago" + (periodoTxt ? " — " + periodoTxt : "") + " — " + nombreCompletoEmpleado(match),
        nombreArchivo: "Colilla_" + nombreCompletoEmpleado(match).replace(/[^a-zA-Z0-9]+/g,"_") + "_" + reg.periodoInicio.replace(/\//g,"-") + ".pdf",
        claveOrigen: CATALOGS.empleados.prefix + match.key,
        empleadoCedula: match.IDENTIFICACION_EMP || null,
        empleadoNombre: nombreCompletoEmpleado(match) || null,
      });
      archivados++;
      clavesYaArchivadas.add(clave);
    }catch(e){
      sinCoincidencia.push(Object.assign({}, reg, { errorArchivo: e.message }));
    }
  }
  return { archivados, duplicados, sinCoincidencia, total: registros.length };
}

async function onColillasPdfSelected(inputEl){
  const files = inputEl.files ? Array.from(inputEl.files) : [];
  if (files.length === 0) return;
  const statusEl = document.getElementById("colillas-pdf-status");
  let textoCombinado = "";
  let leidos = [];
  let archivadosTotal = 0;
  let sinArchivarTotal = 0;
  let duplicadosTotal = 0;
  let sinArchivarDetalle = [];
  // Se carga una sola vez y se comparte entre todos los archivos de esta
  // subida, así detecta tanto "esta colilla ya estaba archivada de antes"
  // como "este mismo lote trae la misma colilla repetida".
  let clavesYaArchivadas;
  try{
    clavesYaArchivadas = await cargarClavesColillasArchivadas();
  }catch(e){
    clavesYaArchivadas = new Set(); // si falla la consulta, no bloquea la subida — solo no filtra duplicados de antes
  }
  for (const file of files){
    statusEl.textContent = `Leyendo ${file.name} (${leidos.length + 1} de ${files.length})…`;
    try{
      const texto = await extraerTextoPDF(file);
      const moneda = detectarMonedaArchivo(file.name);
      textoCombinado += `\n[[MONEDA:${moneda}]]\n` + texto + "\n";
      leidos.push(file.name + (moneda === "USD" ? " (dólares)" : ""));
    }catch(e){
      statusMsg(`No se pudo leer "${file.name}": ${e.message} — como alternativa, abre ese PDF, copia el texto y pégalo abajo.`, false);
      continue;
    }
    // Archiva la colilla individual de cada empleado que aparezca en este PDF —
    // aparte de actualizar el salario (abajo), para que quede un PDF descargable
    // por persona. Si esto falla, no debe impedir que el salario sí se actualice.
    try{
      statusEl.textContent = `Archivando colillas individuales de ${file.name}…`;
      const resultado = await archivarColillasPDF(file, clavesYaArchivadas);
      archivadosTotal += resultado.archivados;
      sinArchivarTotal += resultado.sinCoincidencia.length;
      duplicadosTotal += resultado.duplicados;
      sinArchivarDetalle.push(...resultado.sinCoincidencia.map(r => Object.assign({ archivo: file.name }, r)));
    }catch(e){
      statusMsg(`Se leyó "${file.name}" pero no se pudieron archivar las colillas individuales: ${e.message}`, false);
    }
  }
  if (leidos.length > 0){
    document.getElementById("colillas-textarea").value = textoCombinado;
    statusEl.textContent = `PDF(s) leído(s): ${leidos.join(", ")}. Procesando…`;
    try{
      await procesarColillas();
      statusEl.textContent = "✅ " + leidos.length + " PDF(s) procesado(s): " + leidos.join(", ") +
        (archivadosTotal ? ` — ${archivadosTotal} colilla(s) individual(es) archivada(s)` +
          (sinArchivarTotal ? ` (${sinArchivarTotal} sin coincidencia)` : "") +
          (duplicadosTotal ? ` (${duplicadosTotal} ya estaban archivadas, no se repitieron)` : "") + "." : "") +
        (!archivadosTotal && duplicadosTotal ? ` — ${duplicadosTotal} colilla(s) ya estaban archivadas, no se repitieron.` : "");
      // renderColillasPreview() (llamado dentro de procesarColillas) ya
      // reemplazó el contenido de #colillas-resultados con lo que dice el
      // emparejado por NOMBRE sobre texto completo — eso puede coincidir aunque
      // el recorte página-por-página que archiva el PDF individual haya
      // fallado para esa misma persona. Sin esto, esa falla quedaba invisible:
      // solo se veía "(N sin coincidencia)" en el status, sin decir quién ni
      // por qué, así que agregamos el detalle en un bloque aparte.
      if (sinArchivarDetalle.length){
        const wrap = document.getElementById("colillas-resultados");
        const bloque = document.createElement("div");
        bloque.className = "section-card";
        bloque.style.cssText = "margin-top:10px; border-color:#B3261E;";
        bloque.innerHTML = `<div class="section-body">
          <div style="font-weight:700; color:#B3261E; margin-bottom:6px;">🧾 Colilla individual NO archivada — ${sinArchivarDetalle.length} (esto es aparte de la actualización de salario de arriba):</div>
          <div style="font-size:11.5px; color:var(--ink-soft); margin-bottom:6px;">Se leyó el nombre/número en esta página del PDF pero no coincidió con ningún empleado de tu lista al intentar guardar su colilla individual — revisa número, cédula y nombre en su ficha.</div>
          ${sinArchivarDetalle.map(r => `<div style="font-size:12px; padding:3px 0;">• ${escapeHtml(r.nombre||"(nombre no leído)")} — № ${escapeHtml(r.numero||"—")}${r.cedula ? ` — cédula ${escapeHtml(r.cedula)}` : ""}${r.errorArchivo ? ` — error: ${escapeHtml(r.errorArchivo)}` : ""} <span style="color:var(--ink-soft);">(${escapeHtml(r.archivo)})</span></div>`).join("")}
        </div>`;
        if (wrap) wrap.appendChild(bloque);
      }
    }catch(e){
      statusEl.textContent = "⚠️ El PDF se leyó pero no se pudo procesar: " + e.message;
    }
  } else {
    statusEl.textContent = "";
  }
  inputEl.value = "";
}

// ---------- colillas archivadas: ver y descargar ----------
// Reutiliza el mismo modal genérico que "Datos incompletos" / "Duplicados"
// (index.html: #modal-incompletos), solo cambiando título y contenido.
async function mostrarModalColillasArchivadas(){
  const body = document.getElementById("modal-incompletos-body");
  document.getElementById("modal-incompletos").querySelector(".modal-head span").textContent = "📋 Colillas de pago archivadas";
  body.innerHTML = `<div class="empty-state">Cargando…</div>`;
  document.getElementById("modal-incompletos").classList.add("open");
  try{
    const docs = await window.sdgApi.documentos({ tipo: "colilla_pago" });
    window._colillasArchivadasCache = docs;
    if (!docs.length){
      body.innerHTML = `<div class="empty-state">Todavía no hay colillas archivadas — se archivan solas la próxima vez que subas un PDF de planilla en "Subir PDF(s) de colillas".</div>`;
      return;
    }
    docs.sort((a,b) => (b.emitido_en||"").localeCompare(a.emitido_en||""));

    // Agrupadas por empleado (cédula si la hay, si no la clave del registro,
    // si no el nombre) — así "Descargar todas" puede ser por trabajador y no
    // arrastrar las de todo el mundo cuando solo se quiere una persona.
    const grupos = [];
    const porClave = {};
    docs.forEach(d => {
      const claveGrupo = d.empleado_cedula || d.clave_origen || d.empleado_nombre || d.id;
      if (!porClave[claveGrupo]){
        porClave[claveGrupo] = { nombre: d.empleado_nombre || "Sin nombre", docs: [] };
        grupos.push(porClave[claveGrupo]);
      }
      porClave[claveGrupo].docs.push(d);
    });
    grupos.sort((a,b) => a.nombre.localeCompare(b.nombre, "es"));

    body.innerHTML = `<div style="font-size:12.5px; color:var(--ink-soft); margin-bottom:10px;">${docs.length} colilla(s) archivada(s) de ${grupos.length} trabajador(es).</div>
      <button class="btn" style="width:100%; margin-bottom:12px;" onclick="descargarTodasLasColillas()">⬇️ Descargar absolutamente todas (${docs.length})</button>` +
      grupos.map((g, gi) => `
        <div style="margin-bottom:12px; padding-bottom:10px; border-bottom:1px solid var(--paper-line);">
          <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:4px;">
            <div style="font-weight:700; font-size:12.5px;">${escapeHtml(g.nombre)} <span style="color:var(--ink-soft); font-weight:400;">(${g.docs.length})</span></div>
            <button class="btn primary" style="padding:5px 10px; font-size:11px; flex-shrink:0;" onclick="descargarColillasDeGrupo(${gi})">⬇️ Descargar todas de este trabajador</button>
          </div>
          ${g.docs.map(d => `
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:4px 0;">
              <div style="font-size:11px; color:var(--ink-soft); min-width:0;">${d.emitido_en ? new Date(d.emitido_en).toLocaleDateString("es-CR") : "—"} · ${escapeHtml(d.titulo)}</div>
              <a class="btn" style="padding:4px 9px; font-size:10.5px; flex-shrink:0;" href="${window.sdgApi.urlDescarga(d.id)}" target="_blank" rel="noopener">⬇️</a>
            </div>`).join("")}
        </div>`).join("");
    window._colillasArchivadasGrupos = grupos;
  }catch(e){ body.innerHTML = `<div class="empty-state">No se pudo cargar la lista: ${escapeHtml(e.message)}</div>`; }
}

async function descargarVariasColillas(docs){
  for (const d of docs){
    const a = document.createElement("a");
    a.href = window.sdgApi.urlDescarga(d.id);
    a.download = d.nombre_archivo || "colilla.pdf";
    document.body.appendChild(a);
    a.click();
    a.remove();
    await new Promise(r => setTimeout(r, 300)); // da tiempo entre una y otra para que el navegador no las bloquee
  }
}

async function descargarTodasLasColillas(){
  await descargarVariasColillas(window._colillasArchivadasCache || []);
}

async function descargarColillasDeGrupo(idx){
  const grupo = (window._colillasArchivadasGrupos || [])[idx];
  if (!grupo) return;
  await descargarVariasColillas(grupo.docs);
}

// ---------- colillas faltantes: calendario fijo de planilla (1 y 16) ----------
// La empresa paga los días 15 y 30 (Reglamento Interno / Handbook), así que el
// "período actual a revisar" se calcula del calendario, NO de cuándo alguien
// subió el último PDF — antes, si nadie había subido nada todavía ese mes, el
// sistema no tenía forma de saber qué período tocaba revisar.
//   día 1  → toca revisar el período 16–fin del MES ANTERIOR (pagado el 30)
//   día 16 → toca revisar el período 1–15 del mes actual (pagado el 15)
// Devuelve el checkpoint más reciente que ya pasó, con las fechas del período
// que le corresponde vigilar.
function checkpointActualPlanilla(hoy){
  const cursor = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate());
  for (let i = 0; i < 40; i++){ // nunca hay que retroceder más de ~40 días para encontrar un 1 o un 16
    const dia = cursor.getDate();
    if (dia === 1){
      const finPeriodo = new Date(cursor.getFullYear(), cursor.getMonth(), 0); // último día del mes anterior
      const inicioPeriodo = new Date(finPeriodo.getFullYear(), finPeriodo.getMonth(), 16);
      return { checkDate: new Date(cursor), periodoInicio: inicioPeriodo, periodoFin: finPeriodo };
    }
    if (dia === 16){
      const inicioPeriodo = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
      const finPeriodo = new Date(cursor.getFullYear(), cursor.getMonth(), 15);
      return { checkDate: new Date(cursor), periodoInicio: inicioPeriodo, periodoFin: finPeriodo };
    }
    cursor.setDate(cursor.getDate() - 1);
  }
  return null;
}

function fechaISO(d){
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}

// A un empleado nuevo no se le puede exigir una colilla que todavía no le
// corresponde: se vuelve "elegible" a partir del primer checkpoint (1 o 16)
// que ocurra DESPUÉS de su fecha de ingreso — nunca antes. Ej.: ingresa el 26
// de agosto (cae en el rango 16–31) → elegible desde el 1 de septiembre.
function empleadoElegibleParaColilla(fechaIngresoStr, checkDate){
  const fechaIngreso = parseFechaFlexible(fechaIngresoStr);
  if (!fechaIngreso) return true; // sin fecha registrada no se puede excluir — se revisa por seguridad
  const dia = fechaIngreso.getDate();
  const fechaDesdeQueAplica = dia <= 15
    ? new Date(fechaIngreso.getFullYear(), fechaIngreso.getMonth(), 16)
    : new Date(fechaIngreso.getFullYear(), fechaIngreso.getMonth() + 1, 1);
  return checkDate >= fechaDesdeQueAplica;
}

// Compartido entre el modal "Ver faltantes" y el banner del portal — evita
// duplicar la carga de empleados/documentos y la lógica de elegibilidad.
async function evaluarColillasFaltantes(){
  const hoy = new Date();
  const checkpoint = checkpointActualPlanilla(hoy);
  const [empleadosDB, docs] = await Promise.all([
    cargarEmpleadosDB(),
    window.sdgApi.documentos({ tipo: "colilla_pago" }),
  ]);
  const activos = empleadosDB.filter(e => !e.ARCHIVADO);
  const elegibles = activos.filter(e => empleadoElegibleParaColilla(e.FECHA_INGRESO_EMP, checkpoint.checkDate));
  // Colilla "de este período" = archivada en cualquier momento desde que el
  // período empezó hasta hoy — el momento exacto de subida no importa, solo
  // que corresponda a este período (guardada por su propia fecha de subida).
  const inicioISO = fechaISO(checkpoint.periodoInicio);
  const cedulasConColilla = new Set(
    docs.filter(d => (d.emitido_en || "").slice(0,10) >= inicioISO)
        .map(d => d.empleado_cedula).filter(Boolean)
  );
  const faltantes = elegibles.filter(e => e.IDENTIFICACION_EMP && !cedulasConColilla.has(e.IDENTIFICACION_EMP));
  const periodoTexto = `${checkpoint.periodoInicio.toLocaleDateString("es-CR")} al ${checkpoint.periodoFin.toLocaleDateString("es-CR")}`;
  return { checkpoint, activos, elegibles, faltantes, periodoTexto };
}

async function mostrarModalColillasFaltantes(){
  const body = document.getElementById("modal-incompletos-body");
  document.getElementById("modal-incompletos").querySelector(".modal-head span").textContent = "⚠️ Colillas de pago faltantes";
  body.innerHTML = `<div class="empty-state">Revisando…</div>`;
  document.getElementById("modal-incompletos").classList.add("open");
  try{
    const { elegibles, faltantes, periodoTexto } = await evaluarColillasFaltantes();

    if (faltantes.length === 0){
      body.innerHTML = `<div style="color:var(--leaf); font-weight:700;">✅ Todos los empleados que ya deben tener colilla del período ${periodoTexto} la tienen archivada.</div>`;
      return;
    }
    body.innerHTML = `<div style="font-size:12.5px; color:var(--ink-soft); margin-bottom:10px;">${faltantes.length} de ${elegibles.length} empleados que ya deben tener colilla del período <b>${periodoTexto}</b> no la tienen archivada.</div>` +
      faltantes.map(e => `
        <div id="faltante-${escapeHtml(e.key)}" style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:6px 0; border-bottom:1px solid var(--paper-line);">
          <div style="font-size:12.5px;"><b>${escapeHtml(nombreCompletoEmpleado(e))}</b> — falta colilla de pago</div>
          <div style="display:flex; gap:6px; flex-shrink:0;">
            <button class="btn" style="padding:4px 10px; font-size:11px;" onclick="irASubirColilla();">Ver →</button>
            <button class="btn" style="padding:4px 10px; font-size:11px;" onclick="document.getElementById('faltante-${escapeHtml(e.key)}').remove();">Aceptar</button>
          </div>
        </div>`).join("");
  }catch(e){ body.innerHTML = `<div class="empty-state">No se pudo revisar la lista: ${escapeHtml(e.message)}</div>`; }
}

// Acceso directo desde "Colillas de pago faltantes" hasta donde se suben de
// verdad — el módulo de Datos (la subida es por lote de PDFs que el sistema
// reparte solo por número de empleado/cédula/nombre, así que no hay un
// destino "de este empleado en particular" al que saltar; lo que sí se
// puede hacer es llevar de una vez a ese uploader, en vez de dejar que la
// persona tenga que acordarse dónde queda dentro del menú Datos).
function irASubirColilla(){
  cerrarModalIncompletos();
  showTab("datos");
  setTimeout(() => {
    const boton = document.querySelector('#colillas-panel button[onclick*="colillas-pdf-input"]');
    if (!boton) return;
    boton.scrollIntoView({ behavior: "smooth", block: "center" });
    boton.classList.add("resaltado-temporal");
    setTimeout(() => boton.classList.remove("resaltado-temporal"), 2000);
  }, 50);
}

// ---------- missing-data popup ----------
function evaluarCamposFaltantes(e){
  const faltan = [];
  if (!e.NOMBRE_EMP) faltan.push("Nombre");
  if (!e.APELLIDOS_EMP) faltan.push("Apellidos");
  if (!e.IDENTIFICACION_EMP || !/^\d-\d{4}-\d{4}$/.test(e.IDENTIFICACION_EMP)) faltan.push("Cédula (formato completo)");
  if (!e.PUESTO_KEY && !e.DEPARTAMENTO_EMP) faltan.push("Puesto");
  if (!e.FECHA_INGRESO_EMP) faltan.push("Fecha de ingreso");
  if (e.MONEDA_SALARIO_EMP === "USD" ? !e.SALARIO_USD_EMP : !e.SALARIO_EMP) faltan.push("Salario");
  if (!e.CELULAR_EMP) faltan.push("Teléfono personal");
  if (!e.CORREO_EMP) faltan.push("Correo electrónico");
  if (!e.BANCO_EMP) faltan.push("Banco");
  if (!e.NUMERO_CUENTA_EMP){
    faltan.push("Número de cuenta");
  } else if ((e.TIPO_CUENTA_EMP || "iban") === "iban" && !/^CR\d{20}$/.test(e.NUMERO_CUENTA_EMP.replace(/\s/g,"").toUpperCase())){
    faltan.push("Cuenta IBAN (CR + 20 dígitos)");
  }
  if (!e.ADJUNTO_ID_EMP) faltan.push("Foto de cédula/pasaporte");
  if (!e.ADJUNTO_CUENTA_EMP) faltan.push("Foto de cuenta bancaria");
  if (!e.ESTADO_CIVIL_EMP) faltan.push("Estado civil");
  if (e.HIJOS_EMP_SI === undefined) faltan.push("Hijos (sí/no)");
  if (e.ENFERMEDAD_CRONICA_EMP_SI === undefined) faltan.push("Enfermedad crónica (sí/no)");
  if (e.MEDICAMENTOS_CRONICOS_EMP_SI === undefined) faltan.push("Medicamentos crónicos (sí/no)");
  if (!e.FECHA_NACIMIENTO_EMP) faltan.push("Fecha de nacimiento");
  if (!e.CONTACTO_EMERGENCIA_NOMBRE) faltan.push("Nombre de contacto de emergencia");
  if (!e.CONTACTO_EMERGENCIA_ID) faltan.push("Cédula de contacto de emergencia");
  if (!e.CONTACTO_EMERGENCIA_TEL) faltan.push("Teléfono de contacto de emergencia");
  return faltan;
}

async function mostrarModalIncompletos(){
  const body = document.getElementById("modal-incompletos-body");
  document.getElementById("modal-incompletos").querySelector(".modal-head span").textContent = "👁️ Datos incompletos por empleado";
  body.innerHTML = `<div class="empty-state">Revisando…</div>`;
  document.getElementById("modal-incompletos").classList.add("open");
  try{
    const res = await window.storage.list(CATALOGS.empleados.prefix, false);
    const keys = (res && res.keys) || [];
    const empleados = await Promise.all(keys.map(async k => {
      const r = await window.storage.get(k, false);
      const v = r && r.value ? JSON.parse(r.value) : {};
      return { key: k.replace(CATALOGS.empleados.prefix,""), ...v };
    }));
    const activos = empleados.filter(e => !e.ARCHIVADO);
    const conFaltantes = activos.map(e => ({ e, faltan: evaluarCamposFaltantes(e) })).filter(x => x.faltan.length > 0);
    conFaltantes.sort((a,b) => b.faltan.length - a.faltan.length);

    if (conFaltantes.length === 0){
      body.innerHTML = `<div style="color:var(--leaf); font-weight:700;">✅ Todos los empleados activos tienen sus datos completos.</div>`;
      return;
    }
    body.innerHTML = `<div style="font-size:12.5px; color:var(--ink-soft); margin-bottom:10px;">${conFaltantes.length} de ${activos.length} empleados tienen datos pendientes.</div>` +
      conFaltantes.map(({e, faltan}) => `
        <div style="margin-bottom:12px; padding-bottom:10px; border-bottom:1px solid var(--paper-line);">
          <div style="font-weight:700; color:var(--navy-deep);">${escapeHtml(nombreCompletoEmpleado(e) || e.key)} <span style="font-weight:400; color:#B3261E; font-size:11px;">(${faltan.length} pendiente${faltan.length>1?"s":""})</span></div>
          <div style="font-size:11.5px; color:#8a3b34; margin-top:2px;">${faltan.map(escapeHtml).join(" · ")}</div>
          <button class="btn" style="padding:5px 10px; font-size:11px; margin-top:5px;" onclick="cerrarModalIncompletos(); openCatalogForm('empleados','${e.key.replace(/'/g,"\\'")}');">Completar ahora</button>
        </div>`).join("");
  }catch(e){ body.innerHTML = `<div class="empty-state">No se pudo revisar la lista.</div>`; }
}

function cerrarModalIncompletos(){
  document.getElementById("modal-incompletos").classList.remove("open");
}

// ---------- duplicate detection & merge ----------
function contarCamposLlenos(e){
  return Object.keys(e).filter(k => e[k] && k !== "key" && k !== "HISTORIAL").length;
}

async function buscarDuplicados(){
  const res = await window.storage.list(CATALOGS.empleados.prefix, false);
  const keys = (res && res.keys) || [];
  const empleados = await Promise.all(keys.map(async k => {
    const r = await window.storage.get(k, false);
    const v = r && r.value ? JSON.parse(r.value) : {};
    return { key: k.replace(CATALOGS.empleados.prefix,""), ...v };
  }));
  const grupos = {};
  empleados.forEach(e => {
    const ced = (e.IDENTIFICACION_EMP || "").replace(/\D/g,"");
    const num = (e.NUMERO_EMPLEADO || "").replace(/^0+/,"");
    const criterio = ced ? "c:"+ced : (num ? "n:"+num : null);
    if (!criterio) return;
    if (!grupos[criterio]) grupos[criterio] = [];
    grupos[criterio].push(e);
  });
  return Object.values(grupos).filter(g => g.length > 1);
}

async function mostrarModalDuplicados(){
  const body = document.getElementById("modal-incompletos-body");
  document.getElementById("modal-incompletos").querySelector(".modal-head span").textContent = "🔀 Empleados duplicados";
  body.innerHTML = `<div class="empty-state">Revisando…</div>`;
  document.getElementById("modal-incompletos").classList.add("open");
  try{
    const grupos = await buscarDuplicados();
    if (grupos.length === 0){
      body.innerHTML = `<div style="color:var(--leaf); font-weight:700;">✅ No se encontraron empleados duplicados (comparando por cédula y número de empleado).</div>`;
      return;
    }
    body.innerHTML = `<div style="font-size:12.5px; color:var(--ink-soft); margin-bottom:10px;">Se encontraron ${grupos.length} grupo(s) de posibles duplicados — misma cédula o número de empleado guardados dos veces.</div>` +
      grupos.map((g, gi) => `
        <div style="margin-bottom:14px; padding-bottom:10px; border-bottom:1px solid var(--paper-line);">
          ${g.map(e => `<div style="font-size:12px; padding:4px 0;"><b>${escapeHtml(nombreCompletoEmpleado(e))}</b> — ${escapeHtml(e.DEPARTAMENTO_EMP||"")} · ${e.MONEDA_SALARIO_EMP === "USD" ? (e.SALARIO_USD_EMP ? "$"+Number(e.SALARIO_USD_EMP).toLocaleString("en-US") : "—") : (e.SALARIO_EMP ? "₡"+Number(e.SALARIO_EMP).toLocaleString("es-CR") : "—")} · ${e.IDENTIFICACION_EMP||"sin cédula"} · № ${e.NUMERO_EMPLEADO||"—"}</div>`).join("")}
          <button class="btn primary" style="padding:6px 12px; font-size:11.5px; margin-top:4px;" onclick="fusionarDuplicados(${gi})">🔀 Fusionar en uno solo</button>
        </div>`).join("");
    window._duplicadosCache = grupos;
  }catch(e){ body.innerHTML = `<div class="empty-state">No se pudo revisar la lista.</div>`; }
}

async function fusionarDuplicados(gi){
  const grupo = (window._duplicadosCache || [])[gi];
  if (!grupo || grupo.length < 2) return;
  // keep whichever record has the most complete data; merge in any missing fields
  // from the others, combine their bitácoras, and delete the redundant records.
  grupo.sort((a,b) => contarCamposLlenos(b) - contarCamposLlenos(a));
  const principal = grupo[0];
  const historialCombinado = [];
  grupo.forEach(e => { if (Array.isArray(e.HISTORIAL)) historialCombinado.push(...e.HISTORIAL); });
  historialCombinado.sort((a,b) => (b.fecha||"").localeCompare(a.fecha||""));

  const fusionado = Object.assign({}, ...grupo.slice().reverse(), principal);
  fusionado.HISTORIAL = historialCombinado;
  fusionado.HISTORIAL.unshift({ fecha: fmtFecha(new Date().toISOString()), texto: `Registro fusionado automáticamente (se eliminaron ${grupo.length - 1} duplicado(s)).` });
  delete fusionado.key;

  const key = CATALOGS.empleados.prefix + principal.key;
  await window.storage.set(key, JSON.stringify(fusionado), false);
  for (const dup of grupo.slice(1)){
    await window.storage.delete(CATALOGS.empleados.prefix + dup.key, false);
  }
  statusMsg(`Fusionado: "${nombreCompletoEmpleado(principal)}" — se eliminaron ${grupo.length - 1} duplicado(s).`);
  mostrarModalDuplicados();
}

