// ==========================================================================
// Módulo de Días Libres y Vacaciones — saldo acumulado, solicitudes con
// aprobación, reglas especiales del reglamento interno, calendario y
// reportes. Reutiliza horas_extra: como fuente única de "qué pasó cada día"
// (igual que ya hacen permiso sin goce y vacaciones por carta) para que el
// Reporte de horarios para pago de planilla no tenga que mirar dos lugares.
// ==========================================================================
const SOLICITUD_AUSENCIA_PREFIX = "solicitud_ausencia:";

// Reglas de negocio fijas (especificación del módulo, secciones 2 y 4-5):
// 1 día por cada mes completo trabajado — 12 días al año, la forma
// simplificada que se usa acá del derecho a vacaciones del Art. 153 CT (2
// semanas por cada 50 semanas laboradas).
const ACUMULACION_MENSUAL_VACACIONES = 1; // días por mes trabajado
// La ley no fija un tope de acumulación (Art. 159 CT solo limita cuándo se
// puede APLAZAR tomarlas, no cuánto se puede juntar); 24 = dos años
// completos sin tomar ni un día, como margen interno razonable antes de
// obligar a que se usen — es un valor de configuración, ajustable.
const TOPE_SALDO_VACACIONES = 24;

// El ciclo fijo compartido (1° de diciembre a 30 de noviembre) es una
// política nueva que arranca este 1° de diciembre de 2026 — no aplica hacia
// atrás. Sin este piso, a un empleado antiguo (ingresado, por ejemplo, en
// 2015) el cálculo lo habría pasado al ciclo fijo en algún 1° de diciembre
// de hace años, mucho antes de que la política existiera. Hasta que llegue
// esta fecha, TODOS siguen acumulando por su propio aniversario, sin
// importar cuánta antigüedad tengan.
const INICIO_CICLO_FIJO_VACACIONES = new Date(2026, 11, 1);
const ANTICIPACION_MINIMA_DIAS_SOLICITUD = 15;
const DIA_CORTE_MENSUAL_SOLICITUD = 30;

// SCP Corcovado Wilderness Lodge acumuló excedentes de vacaciones muy
// grandes por antigüedad (años sin tope real). Por pedido de gerencia, SOLO
// para el cálculo del saldo de vacaciones de esa propiedad, el período
// actual se trata como si arrancara el 1° de diciembre de 2025 — sin tocar
// FECHA_INGRESO_EMP (que sigue rigiendo antigüedad, período de prueba,
// planilla, incidencias, etc. tal cual está en la ficha del empleado). A
// quien ingresó DESPUÉS de esta fecha no se le adelanta el arranque: sigue
// acumulando desde su propio ingreso real (ver calcularSaldoVacaciones,
// que aplica esto tomando el más tardío entre los dos). Ninguna otra
// propiedad se ve afectada.
const RESET_VACACIONES_CORCOVADO = { propiedad: "corcovado", fecha: new Date(2025, 11, 1) };

const TIPOS_SOLICITUD_AUSENCIA = {
  vacaciones: { label: "Vacaciones", emoji: "🏖️", consumeSaldo: true, requiereComprobante: false, colorHex: "FFF5D06B" },
  // Descanso programado del rol (el día libre semanal o el bloque que le
  // corresponde al empleado) — no es vacación (no resta del saldo
  // acumulado) ni permiso sin goce (no es una excepción sin pago). Alimenta
  // el mismo contador de "días libres" del reporte de horario de planilla
  // que hasta ahora solo se llenaba con "vacaciones" (ver
  // calcularResumenQuincena) — antes no había forma de registrar el
  // descanso regular sin usar por error el tipo Vacaciones.
  dia_libre: { label: "Día libre", emoji: "🛌", consumeSaldo: false, requiereComprobante: false, colorHex: "FFB3E6B3" },
  permiso_sin_goce: { label: "Permiso sin goce", emoji: "📄", consumeSaldo: false, requiereComprobante: false, colorHex: "FF8FD3E8" },
  ausencia_medica: { label: "Ausencia médica (cita)", emoji: "🩺", consumeSaldo: false, requiereComprobante: true, colorHex: "FFE68A8A" },
};

function isoDeHoy(){ return isoDeFechaLocal(new Date()); }

// ---------- Incapacidades (CCSS/INS) ----------
// Registro propio (no reutiliza solicitud_ausencia:) porque necesita datos
// que las demás ausencias no tienen: tipo legal (distinto tratamiento cada
// uno: enfermedad común, riesgo de trabajo — Art. 218 CT/INS obliga a veces
// a completar salario, maternidad), número de boleta oficial para trazar
// contra la CCSS/INS, encadenado de prórrogas (la CCSS extiende la misma
// incapacidad varias veces) y el salario diario promedio de referencia para
// que RH sepa cuánto le corresponde completar a la empresa.
//
// No pasa por cola de aprobación ni se puede anular: una incapacidad no es
// una decisión de la empresa (la boleta CCSS/INS ya la respalda), así que
// registrarla es un hecho consumado — solo existe para calcular su pago en
// colillas, no para que alguien la apruebe, niegue o revierta después.
// Al registrarla se justifican los días en horas_extra: (mismo mecanismo que
// usan vacaciones/permiso — ver justificarRangoISO) con TIPO_DIA
// "incapacidad" y ESTADO "aprobada" (el estado fijo que usa ese ledger para
// que el día cuente en calendario/planilla — no es una aprobación de la
// incapacidad en sí), que es lo que diasIncapacidadAprobados() lee para
// pausar la acumulación de vacaciones (Art. 160 CT) — no hace falta tocar
// calcularSaldoVacaciones para nada.
const INCAPACIDAD_PREFIX = "incapacidad:";
const TIPOS_INCAPACIDAD = {
  enfermedad_comun: { label: "Enfermedad común", emoji: "🤒" },
  riesgo_trabajo: { label: "Riesgo de trabajo", emoji: "⚠️" },
  maternidad: { label: "Maternidad", emoji: "🤰" },
};
// ---------- Motor de reglas de nómina para incapacidades ----------
// Traducción directa del pseudocódigo de nómina: para un registro YA
// guardado, calcula cuánto le corresponde pagar al patrono (el resto lo
// cubre el subsidio CCSS/INS) y cuántos de sus días cuentan para vacaciones
// y para aguinaldo. Es una lectura derivada — informativa por ahora, para
// el futuro módulo de recibos de nómina/SICERE — y NO toca
// calcularSaldoVacaciones (ver nota de conflicto más abajo).
//
// La regla es la misma para las 4 propiedades — no hay configuración por
// propiedad: en riesgo de trabajo el patrono no completa nada, el INS asume
// el subsidio completo (regla estándar de ley).
//
// Devuelve { montoAPagarPlanilla, diasValidosAguinaldo, diasValidosVacaciones }.
// SALARIO_DIARIO_PROMEDIO se calcula solo, al registrar la incapacidad, a
// partir del salario mensual ya guardado en la ficha del empleado (ver
// salarioDiarioDeEmpleado) — nunca se captura a mano. montoAPagarPlanilla es
// null solo si a ese empleado no se le había guardado un salario en su ficha.
//
// ⚠️ Los "días válidos para vacaciones" que exige este motor (todos los días
// de enfermedad_comun/riesgo_trabajo/maternidad SÍ acumulan) contradicen a
// calcularSaldoVacaciones, que hoy hace lo contrario por diseño (Art. 160
// CT tal como se implementó ahí: un período con incapacidad NO acredita —
// "pausa" en vez de "acumula"). Este motor se dejó aparte, sin tocar esa
// función, hasta confirmar cuál de las dos reglas debe regir el saldo real.
function calcularPagoIncapacidad(incapacidad){
  const dias = incapacidad.DIAS || 0;
  const salarioDiario = (incapacidad.SALARIO_DIARIO_PROMEDIO || incapacidad.SALARIO_DIARIO_PROMEDIO === 0) ? incapacidad.SALARIO_DIARIO_PROMEDIO : null;
  let montoAPagarPlanilla = 0;
  let diasValidosAguinaldo = 0;
  let diasValidosVacaciones = 0;

  switch (incapacidad.TIPO_INCAPACIDAD){
    case "enfermedad_comun": {
      // Las vacaciones sí acumulan siempre por ley; el aguinaldo no.
      diasValidosVacaciones = dias;
      diasValidosAguinaldo = 0;
      if (incapacidad.ES_PRORROGA){
        // Prórroga: todo asumido al 60% por la CCSS, el patrono paga 0.
        montoAPagarPlanilla = 0;
      } else if (salarioDiario === null){
        montoAPagarPlanilla = null;
      } else {
        for (let dia = 1; dia <= dias; dia++){
          if (dia <= 3) montoAPagarPlanilla += salarioDiario * 0.50; // primeros 3 días: patrono paga 50%
          // día 4 en adelante: patrono paga 0% (CCSS asume el 60%)
        }
      }
      break;
    }
    case "riesgo_trabajo": {
      // Todo lo asume el INS — el patrono no completa nada, en ninguna propiedad.
      diasValidosVacaciones = dias;
      diasValidosAguinaldo = 0;
      montoAPagarPlanilla = 0;
      break;
    }
    case "maternidad": {
      // Acumula TODO (vacaciones y aguinaldo). Patrono paga fijo 50% de todo el período.
      diasValidosVacaciones = dias;
      diasValidosAguinaldo = dias;
      montoAPagarPlanilla = salarioDiario === null ? null : (salarioDiario * dias) * 0.50;
      break;
    }
    default:
      diasValidosVacaciones = dias;
      diasValidosAguinaldo = 0;
      montoAPagarPlanilla = null;
  }

  return { montoAPagarPlanilla, diasValidosAguinaldo, diasValidosVacaciones };
}

async function listarIncapacidades(){
  const res = await window.storage.list(INCAPACIDAD_PREFIX, false);
  const keys = (res && res.keys) || [];
  const registros = await Promise.all(keys.map(async k => {
    try{
      const r = await window.storage.get(k, false);
      const v = r && r.value ? JSON.parse(r.value) : null;
      return v ? { key: k, ...v } : null;
    }catch(e){ return null; }
  }));
  return registros.filter(Boolean);
}

// Salario diario promedio para el cálculo de pago en colillas: sale directo
// del salario mensual bruto ya guardado en la ficha del empleado (SALARIO_EMP
// o SALARIO_USD_EMP según MONEDA_SALARIO_EMP), entre 30 — la misma regla que
// ya usa el cálculo de horas extra (ver salarioHora en renderHorasExtrasPanel)
// para pasar de mensual a diario. Nunca se pide a mano: así siempre coincide
// con lo que ya está en el sistema y se actualiza solo si cambia el salario
// del empleado (queda "congelado" en el registro al momento de crearlo, para
// que un aumento posterior no altere una incapacidad ya registrada).
function salarioDiarioDeEmpleado(emp){
  if (!emp) return { monto: null, moneda: "CRC" };
  const moneda = emp.MONEDA_SALARIO_EMP === "USD" ? "USD" : "CRC";
  const bruto = moneda === "USD" ? emp.SALARIO_USD_EMP : emp.SALARIO_EMP;
  const n = Number(String(bruto || "").replace(/[^0-9.]/g, ""));
  return { monto: (n && !isNaN(n)) ? n / 30 : null, moneda };
}

async function crearIncapacidad({ empKey, tipo, fechaInicio, fechaFin, numeroBoleta, esProrroga, incapacidadOriginalKey, comprobanteDataUrl, comprobanteNombre }){
  if (!TIPOS_INCAPACIDAD[tipo]) throw new Error("Tipo de incapacidad inválido.");
  if (!empKey) throw new Error("Elegí un empleado.");
  if (!fechaInicio || !fechaFin) throw new Error("Elegí las fechas.");
  if (fechaFin < fechaInicio) throw new Error("La fecha de fin no puede ser anterior a la de inicio.");
  const dias = diasEntreFechasISO(fechaInicio, fechaFin);
  const id = `${fechaInicio}-${Date.now()}`;
  const key = INCAPACIDAD_PREFIX + empKey + ":" + id;
  const email = (window.sdgApi && window.sdgApi.sesionActual() && window.sdgApi.sesionActual().email) || "";
  const empRes = await window.storage.get(CATALOGS.empleados.prefix + empKey, false);
  const emp = empRes && empRes.value ? JSON.parse(empRes.value) : null;
  const { monto: salarioDiarioPromedio, moneda: salarioMoneda } = salarioDiarioDeEmpleado(emp);
  const value = {
    EMPLEADO_KEY: empKey,
    TIPO_INCAPACIDAD: tipo,
    ES_PRORROGA: !!esProrroga,
    INCAPACIDAD_ORIGINAL_KEY: esProrroga ? (incapacidadOriginalKey || null) : null,
    NUMERO_BOLETA: (numeroBoleta || "").trim(),
    FECHA_INICIO: fechaInicio,
    FECHA_FIN: fechaFin,
    DIAS: dias,
    SALARIO_DIARIO_PROMEDIO: salarioDiarioPromedio,
    SALARIO_MONEDA: salarioMoneda,
    COMPROBANTE_DATA_URL: comprobanteDataUrl || null,
    COMPROBANTE_NOMBRE: comprobanteNombre || null,
    REGISTRADO_POR: email,
    FECHA_REGISTRO: new Date().toISOString(),
  };
  await window.storage.set(key, JSON.stringify(value), false);
  await justificarRangoISO(empKey, fechaInicio, fechaFin, "incapacidad", "incapacidad_registro", {
    ESTADO: "aprobada",
    APROBADO_POR: email,
    FECHA_DECISION: new Date().toISOString(),
    INCAPACIDAD_KEY: key,
  });
  const tipoLabel = TIPOS_INCAPACIDAD[tipo].label;
  await agregarBitacora(empKey, `Incapacidad registrada (${tipoLabel}${esProrroga ? ", prórroga" : ""}): del ${fmtFecha(fechaInicio + "T00:00:00")} al ${fmtFecha(fechaFin + "T00:00:00")} (${dias} día(s))${numeroBoleta ? " — boleta " + numeroBoleta : ""}.`);
  return key;
}

// Cache del último listado para poblar el selector de prórroga sin
// re-consultar el servidor en cada cambio del <select> de empleado.
let incapacidadesCacheParaProrroga = [];

function actualizarSelectorProrrogaIncapacidad(){
  const empKey = (document.getElementById("incapacidad-empleado") || {}).value;
  const sel = document.getElementById("incapacidad-original");
  if (!sel) return;
  const delEmpleado = incapacidadesCacheParaProrroga.filter(i => i.EMPLEADO_KEY === empKey);
  sel.innerHTML = `<option value="">— Ninguna —</option>` + delEmpleado.map(i =>
    `<option value="${i.key}">${fmtFecha(i.FECHA_INICIO + "T00:00:00")} al ${fmtFecha(i.FECHA_FIN + "T00:00:00")}${i.NUMERO_BOLETA ? " — " + escapeHtml(i.NUMERO_BOLETA) : ""}</option>`
  ).join("");
}

function renderFormularioIncapacidad(empleadosDisponibles){
  const ordenados = empleadosDisponibles.slice().sort(compararPorApellido);
  return `<div class="section-card" style="margin-bottom:14px; border-color:var(--gold);"><div class="section-body">
    <div style="font-weight:700; color:var(--navy-deep); margin-bottom:8px;">📝 Registrar incapacidad</div>
    <p style="font-size:12px; color:var(--ink-soft); margin:0 0 8px;">Es un registro directo para el cálculo de pago en colillas — no pasa por aprobación ni se puede anular. El salario diario se toma automático de la ficha del empleado (no se pide a mano). Pausa la acumulación de vacaciones mientras dure.</p>
    <div style="display:flex; gap:8px; flex-wrap:wrap; align-items:flex-end;">
      <label style="font-size:11.5px; color:var(--ink-soft); display:flex; flex-direction:column; gap:3px; flex:1; min-width:180px;">Empleado
        <select id="incapacidad-empleado" onchange="actualizarSelectorProrrogaIncapacidad()">
          <option value="">— Elegí —</option>
          ${ordenados.map(e => `<option value="${e.key}">${escapeHtml(nombreCompletoEmpleado(e) || e.key)}</option>`).join("")}
        </select>
      </label>
      <label style="font-size:11.5px; color:var(--ink-soft); display:flex; flex-direction:column; gap:3px;">Tipo
        <select id="incapacidad-tipo">
          ${Object.keys(TIPOS_INCAPACIDAD).map(t => `<option value="${t}">${TIPOS_INCAPACIDAD[t].emoji} ${TIPOS_INCAPACIDAD[t].label}</option>`).join("")}
        </select>
      </label>
      <label style="font-size:11.5px; color:var(--ink-soft); display:flex; flex-direction:column; gap:3px;">Desde
        <input type="date" id="incapacidad-desde">
      </label>
      <label style="font-size:11.5px; color:var(--ink-soft); display:flex; flex-direction:column; gap:3px;">Hasta
        <input type="date" id="incapacidad-hasta">
      </label>
      <label style="font-size:11.5px; color:var(--ink-soft); display:flex; flex-direction:column; gap:3px;">N° de boleta (CCSS/INS)
        <input type="text" id="incapacidad-boleta" placeholder="Ej. CCSS-9938472-A">
      </label>
      <label style="font-size:11.5px; color:var(--ink-soft); display:flex; flex-direction:column; gap:3px;">Comprobante (PDF/imagen)
        <input type="file" id="incapacidad-comprobante" accept=".pdf,image/*">
      </label>
    </div>
    <div style="margin-top:8px; display:flex; gap:8px; flex-wrap:wrap; align-items:flex-end;">
      <label style="font-size:12px; color:var(--ink-soft); display:flex; align-items:center; gap:6px;">
        <input type="checkbox" id="incapacidad-es-prorroga" onchange="document.getElementById('incapacidad-prorroga-wrap').style.display = this.checked ? 'flex' : 'none';">
        Es prórroga de una incapacidad anterior
      </label>
      <label id="incapacidad-prorroga-wrap" style="font-size:11.5px; color:var(--ink-soft); display:none; flex-direction:column; gap:3px; flex:1; min-width:220px;">Incapacidad original
        <select id="incapacidad-original"><option value="">— Elegí primero al empleado —</option></select>
      </label>
    </div>
    <button class="btn primary" style="margin-top:10px;" onclick="confirmarRegistroIncapacidad();">✅ Registrar incapacidad</button>
    <div id="incapacidad-status" style="font-size:12px; margin-top:6px;"></div>
  </div></div>`;
}

async function confirmarRegistroIncapacidad(){
  const status = document.getElementById("incapacidad-status");
  const empKey = (document.getElementById("incapacidad-empleado")||{}).value;
  const tipo = (document.getElementById("incapacidad-tipo")||{}).value;
  const fechaInicio = (document.getElementById("incapacidad-desde")||{}).value;
  const fechaFin = (document.getElementById("incapacidad-hasta")||{}).value;
  const numeroBoleta = (document.getElementById("incapacidad-boleta")||{}).value;
  const esProrroga = !!(document.getElementById("incapacidad-es-prorroga")||{}).checked;
  const incapacidadOriginalKey = (document.getElementById("incapacidad-original")||{}).value || null;
  const inputComprobante = document.getElementById("incapacidad-comprobante");
  const archivo = inputComprobante && inputComprobante.files && inputComprobante.files[0];
  try{
    if (!empKey) throw new Error("Elegí un empleado.");
    let comprobanteDataUrl = null, comprobanteNombre = null;
    if (archivo){
      if (archivo.size > 3.5*1024*1024) throw new Error("El comprobante pesa más de 3.5MB — comprímelo o escanea en menor resolución.");
      comprobanteDataUrl = await leerArchivoComoDataUrl(archivo);
      comprobanteNombre = archivo.name;
    }
    await crearIncapacidad({ empKey, tipo, fechaInicio, fechaFin, numeroBoleta, esProrroga, incapacidadOriginalKey, comprobanteDataUrl, comprobanteNombre });
    statusMsg("Incapacidad registrada.");
    renderIncapacidadesPanel();
  }catch(e){
    if (status) status.innerHTML = `<span style="color:#b23b3b;">${escapeHtml(e.message)}</span>`;
  }
}

function renderFilaIncapacidad(i, empleadosPorKey){
  const emp = empleadosPorKey[i.EMPLEADO_KEY];
  const tipo = TIPOS_INCAPACIDAD[i.TIPO_INCAPACIDAD] || { label: i.TIPO_INCAPACIDAD || "—", emoji: "🤒" };
  const r = calcularPagoIncapacidad(i);
  const esUsd = i.SALARIO_MONEDA === "USD";
  const montoTxt = r.montoAPagarPlanilla === null
    ? "sin salario guardado en la ficha del empleado"
    : esUsd
    ? `$${r.montoAPagarPlanilla.toLocaleString("en-US", {minimumFractionDigits:2, maximumFractionDigits:2})}`
    : `₡${Math.round(r.montoAPagarPlanilla).toLocaleString("es-CR")}`;
  const lineaNomina = `<span class="meta">💰 Pago patrono estimado: ${montoTxt} · vacaciones: ${r.diasValidosVacaciones} día(s) · aguinaldo: ${r.diasValidosAguinaldo} día(s)</span><br>`;
  return `<div style="padding:6px 0; border-bottom:1px solid var(--paper-line);">
    <div style="font-size:12.5px;">
      <b>${escapeHtml(emp ? (nombreCompletoEmpleado(emp)||emp.key) : i.EMPLEADO_KEY)}</b> — ${tipo.emoji} ${escapeHtml(tipo.label)}${i.ES_PRORROGA ? " (prórroga)" : ""}<br>
      <span class="meta">${fmtFecha(i.FECHA_INICIO + "T00:00:00")} al ${fmtFecha(i.FECHA_FIN + "T00:00:00")} · ${i.DIAS} día(s)${i.NUMERO_BOLETA ? " · boleta " + escapeHtml(i.NUMERO_BOLETA) : ""}</span><br>
      ${lineaNomina}
    </div>
  </div>`;
}

async function renderIncapacidadesPanel(){
  const panel = document.getElementById("incapacidades-panel");
  if (!panel) return;
  panel.innerHTML = `<div class="empty-state">Cargando…</div>`;
  try{
    const puedeRegistrar = !!(window.sdgApi && window.sdgApi.puedeEditar());
    const [empleados, incapacidades] = await Promise.all([
      cargarEmpleadosDB(), listarIncapacidades(),
    ]);
    const empleadosActivos = empleados.filter(e => !e.ARCHIVADO);
    const empleadosPorKey = {};
    empleadosActivos.forEach(e => { empleadosPorKey[e.key] = e; });
    incapacidadesCacheParaProrroga = incapacidades;

    const hoyISO = isoDeHoy();
    const activas = incapacidades.filter(i => i.FECHA_INICIO <= hoyISO && i.FECHA_FIN >= hoyISO).sort((a,b) => (a.FECHA_FIN||"").localeCompare(b.FECHA_FIN||""));
    const proximasARegresar = activas.filter(i => {
      const diasParaRegreso = Math.round((new Date(i.FECHA_FIN + "T00:00:00") - new Date(hoyISO + "T00:00:00")) / 86400000);
      return diasParaRegreso <= 3;
    });
    const historial = incapacidades
      .filter(i => !(i.FECHA_INICIO <= hoyISO && i.FECHA_FIN >= hoyISO))
      .sort((a,b) => (b.FECHA_INICIO||"").localeCompare(a.FECHA_INICIO||""))
      .slice(0, 30);

    let html = `<div style="margin-bottom:14px;">
      <div style="font-size:18px; font-weight:800; color:var(--navy-deep);">🤒 Incapacidades</div>
      <div style="font-size:12px; color:var(--ink-soft);">Registro con boleta CCSS/INS, incapacidades activas y alerta cuando se acerca la fecha de regreso. Pausa la acumulación de vacaciones automáticamente (Art. 160 CT) mientras está activa.</div>
    </div>`;

    if (proximasARegresar.length){
      html += `<div class="section-card" style="margin-bottom:14px; border-color:var(--gold); background:#FBF6E8;"><div class="section-body">
        <div style="font-weight:700; color:var(--navy-deep); margin-bottom:6px;">⏳ Regreso próximo</div>
        ${proximasARegresar.map(i => {
          const emp = empleadosPorKey[i.EMPLEADO_KEY];
          const diasParaRegreso = Math.round((new Date(i.FECHA_FIN + "T00:00:00") - new Date(hoyISO + "T00:00:00")) / 86400000);
          return `<div style="font-size:12.5px; padding:4px 0;"><b>${escapeHtml(emp ? (nombreCompletoEmpleado(emp)||emp.key) : i.EMPLEADO_KEY)}</b> — regresa el ${fmtFecha(i.FECHA_FIN + "T00:00:00")} (${diasParaRegreso <= 0 ? "hoy o ya pasó" : `en ${diasParaRegreso} día(s)`})</div>`;
        }).join("")}
      </div></div>`;
    }

    if (puedeRegistrar){
      html += renderFormularioIncapacidad(empleadosActivos);
    }

    html += `<div class="section-card" style="margin-bottom:14px;"><div class="section-body">
      <div style="font-weight:700; color:var(--navy-deep); margin-bottom:8px;">📋 Incapacidades activas (${activas.length})</div>
      ${activas.length ? activas.map(i => renderFilaIncapacidad(i, empleadosPorKey)).join("") : `<div class="empty-state" style="padding:10px 0;">Nadie está incapacitado hoy.</div>`}
    </div></div>`;

    html += `<div class="section-card"><div class="section-body">
      <div style="font-weight:700; color:var(--navy-deep); margin-bottom:8px;">🗂️ Historial reciente</div>
      ${historial.length ? historial.map(i => renderFilaIncapacidad(i, empleadosPorKey)).join("") : `<div class="empty-state" style="padding:10px 0;">Sin registros anteriores.</div>`}
    </div></div>`;

    panel.innerHTML = html;
  }catch(e){
    panel.innerHTML = `<div class="empty-state">No se pudo cargar el módulo: ${escapeHtml(e.message || "")}</div>`;
  }
}

// Días de incapacidad ya aprobados (fechas "AAAA-MM-DD") — se leen de los
// mismos registros horas_extra: (TIPO_DIA "incapacidad", ESTADO "aprobada"),
// para no mantener una segunda fuente de la verdad sobre incapacidades.
function diasIncapacidadAprobados(registrosHorasExtra, empKey){
  return registrosHorasExtra
    .filter(r => r.EMPLEADO_KEY === empKey && r.TIPO_DIA === "incapacidad" && r.ESTADO === "aprobada")
    .map(r => r.FECHA);
}

// 1° de diciembre en o después de la fecha dada — el corte anual fijo que
// comparten TODOS los empleados con más de 1 año de antigüedad (no cada
// quien por su propio aniversario), tal como se definió el módulo.
function proximoPrimeroDeDiciembre(d){
  const dic1EsteAnio = new Date(d.getFullYear(), 11, 1);
  return d <= dic1EsteAnio ? dic1EsteAnio : new Date(d.getFullYear() + 1, 11, 1);
}

// Saldo de vacaciones: simulación cronológica, no una fórmula cerrada. Se
// acredita 1 día por cada mes completo trabajado (12 días/año); un período
// con al menos un día de incapacidad aprobada NO acredita — Art. 160 CT: la
// incapacidad pausa el cómputo del tiempo de servicio, no descuenta lo ya
// ganado.
//
// El PASO de los meses cambia según la antigüedad:
// - Primer año: por aniversario personal (mismo día del mes que el
//   ingreso) — "cada mes cumplido desde que entró, acumula 1 día".
// - Desde que cumple 1 año: el conteo pasa al calendario fijo de la
//   empresa (1° de diciembre a 30 de noviembre), igual para todos sin
//   importar la fecha de ingreso de cada quien. El tramo entre el
//   aniversario y el próximo 1° de diciembre NO se pierde ni se acredita
//   de golpe — sigue sumando normal, mes a mes por aniversario, hasta ese
//   1° de diciembre; recién ahí el paso salta al calendario fijo.
// Nunca se resetea el saldo a cero en ese cambio de fase ni en cada 1° de
// diciembre — es una sola cuenta corriente (topada en
// TOPE_SALDO_VACACIONES), para que el saldo disponible quede reflejado con
// flexibilidad en cualquier fecha, sin importar cuándo se pida.
//
// Cada solicitud de VACACIONES aprobada resta sus días en la fecha en que
// arrancan. El orden cronológico importa: si se usan días antes de volver a
// tocar el tope, la acumulación siguiente sí "entra" — sumar todo primero y
// restar el uso al final da un resultado distinto (y equivocado) cuando el
// uso ocurre antes de llegar al tope de nuevo.
function calcularSaldoVacaciones(empleado, solicitudesVacacionesAprobadas, diasIncapacidad, fechaCorte){
  let ingreso = parsearFechaEmpleado(empleado && empleado.FECHA_INGRESO_EMP);
  if (!ingreso || ingreso > fechaCorte) return 0;
  // Reinicio del período de acumulación solo para Corcovado (ver
  // RESET_VACACIONES_CORCOVADO) — únicamente adelanta el arranque de la
  // simulación cuando el ingreso real es anterior a esa fecha; a quien
  // ingresó después no se le adelanta nada, sigue con su ingreso real.
  if (currentPropiedadId === RESET_VACACIONES_CORCOVADO.propiedad && ingreso < RESET_VACACIONES_CORCOVADO.fecha){
    ingreso = RESET_VACACIONES_CORCOVADO.fecha;
  }
  const incapacidadSet = new Set(diasIncapacidad || []);
  const primerAniversario = new Date(ingreso.getFullYear() + 1, ingreso.getMonth(), ingreso.getDate());

  const eventos = [];
  let inicioPeriodo = new Date(ingreso);
  let cicloFijo = false; // true desde el 1° de diciembre en que ya se cumplió 1 año
  while (true){
    let finPeriodo;
    if (cicloFijo){
      finPeriodo = new Date(inicioPeriodo.getFullYear(), inicioPeriodo.getMonth() + 1, 1);
    } else {
      finPeriodo = new Date(inicioPeriodo.getFullYear(), inicioPeriodo.getMonth() + 1, inicioPeriodo.getDate());
      if (finPeriodo >= primerAniversario){
        const proximoDic1Natural = proximoPrimeroDeDiciembre(inicioPeriodo);
        // Nunca antes del piso de la política (INICIO_CICLO_FIJO_VACACIONES),
        // aunque el aniversario de esta persona sea muy anterior a 2026.
        const proximoDic1 = proximoDic1Natural < INICIO_CICLO_FIJO_VACACIONES ? INICIO_CICLO_FIJO_VACACIONES : proximoDic1Natural;
        if (finPeriodo >= proximoDic1){
          finPeriodo = proximoDic1; // el paso "salta" justo al 1° de diciembre, sin saltarse ni repetir un mes
          cicloFijo = true;
        }
      }
    }
    if (finPeriodo > fechaCorte) break;
    let pausado = false;
    const cursorDia = new Date(inicioPeriodo);
    while (cursorDia < finPeriodo){
      if (incapacidadSet.has(isoDeFechaLocal(cursorDia))){ pausado = true; break; }
      cursorDia.setDate(cursorDia.getDate() + 1);
    }
    if (!pausado) eventos.push({ fecha: finPeriodo, tipo: "acredita", dias: ACUMULACION_MENSUAL_VACACIONES });
    inicioPeriodo = finPeriodo;
  }
  (solicitudesVacacionesAprobadas || []).forEach(s => {
    const fecha = new Date(s.FECHA_INICIO + "T00:00:00");
    if (fecha <= fechaCorte) eventos.push({ fecha, tipo: "usa", dias: s.DIAS || 0 });
  });
  // Ajustes manuales (ver agregarAjusteVacaciones) — master/gerente corrige
  // el saldo a mano (típicamente para quitar un excedente que ya se sabe que
  // el empleado disfrutó fuera de este sistema, o para una corrección de
  // arrastre). dias puede ser negativo (quitar) o positivo (otorgar) y se
  // aplica directo, sin el tope de la acumulación automática — es una
  // corrección deliberada, no una acreditación más.
  (empleado && empleado.AJUSTES_VACACIONES || []).forEach(a => {
    const fecha = new Date(a.fecha + "T00:00:00");
    if (fecha <= fechaCorte) eventos.push({ fecha, tipo: "ajuste", dias: a.dias || 0 });
  });
  eventos.sort((a,b) => a.fecha - b.fecha);

  let saldo = 0;
  eventos.forEach(ev => {
    if (ev.tipo === "acredita") saldo = Math.min(saldo + ev.dias, TOPE_SALDO_VACACIONES);
    else if (ev.tipo === "ajuste") saldo = Math.max(0, saldo + ev.dias);
    else saldo = Math.max(0, saldo - ev.dias);
  });
  return saldo;
}

// Ajuste manual del saldo de vacaciones — exclusivo de master/gerente desde
// la UI (renderTablaSaldos). Se guarda como un evento más (con motivo y
// quién lo hizo) en vez de sobrescribir un número suelto, para no perder el
// rastro de por qué cambió. dias negativo quita un excedente; positivo
// otorga días extra (ej. un acuerdo puntual fuera del cálculo automático).
async function agregarAjusteVacaciones(empKey, dias, motivo){
  const fullKey = CATALOGS.empleados.prefix + empKey;
  const res = await window.storage.get(fullKey, false);
  if (!res || !res.value) throw new Error("No se encontró ese empleado.");
  const emp = JSON.parse(res.value);
  if (!Array.isArray(emp.AJUSTES_VACACIONES)) emp.AJUSTES_VACACIONES = [];
  emp.AJUSTES_VACACIONES.push({
    fecha: isoDeHoy(),
    dias,
    motivo: motivo || "",
    hechoPor: (window.sdgApi && window.sdgApi.sesionActual() && window.sdgApi.sesionActual().email) || "",
    hechoEn: new Date().toISOString(),
  });
  await window.storage.set(fullKey, JSON.stringify(emp), false);
  await agregarBitacora(empKey, `Ajuste manual de vacaciones: ${dias > 0 ? "+" : ""}${dias} día(s)${motivo ? " — " + motivo : ""}.`);
}

// Estado del modal de ajuste de saldo — se abre por fechas (calcula los
// días automático, para no tener que contarlos a mano) o por número directo
// (se deja como opción B para ajustes que no corresponden a un rango de
// fechas real, ej. un acuerdo puntual).
let ajusteVacacionesCtx = null;

function pedirAjusteVacaciones(empKey, nombreEmp, saldoActual){
  ajusteVacacionesCtx = { empKey, nombreEmp, saldoActual, modo: "fechas", desde: "", hasta: "", diasManual: "", signo: -1, motivo: "" };
  renderModalAjusteVacaciones();
  document.getElementById("modal-ajuste-vacaciones").classList.add("open");
}

function cerrarModalAjusteVacaciones(){
  const modal = document.getElementById("modal-ajuste-vacaciones");
  if (modal) modal.classList.remove("open");
  ajusteVacacionesCtx = null;
}

function actualizarAjusteVacacionesCtx(campo, valor){
  if (!ajusteVacacionesCtx) return;
  ajusteVacacionesCtx[campo] = valor;
  renderModalAjusteVacaciones();
}

function renderModalAjusteVacaciones(){
  const ctx = ajusteVacacionesCtx;
  const body = document.getElementById("modal-ajuste-vacaciones-body");
  if (!ctx || !body) return;

  const rangoInvalido = ctx.modo === "fechas" && ctx.desde && ctx.hasta && ctx.hasta < ctx.desde;
  let dias = null;
  if (ctx.modo === "fechas"){
    if (ctx.desde && ctx.hasta && !rangoInvalido) dias = diasEntreFechasISO(ctx.desde, ctx.hasta);
  } else {
    const n = parseFloat(String(ctx.diasManual).replace(",", "."));
    if (!isNaN(n) && n > 0) dias = n;
  }
  const ajuste = dias ? dias * ctx.signo : null;

  body.innerHTML = `
    <div style="font-size:12.5px; color:var(--ink-soft); margin-bottom:10px;">Saldo actual de <b>${escapeHtml(ctx.nombreEmp)}</b>: ${ctx.saldoActual} día(s).</div>
    <div class="sino-toggle" style="margin-bottom:10px;">
      <button type="button" class="${ctx.modo==='fechas'?'active':''}" onclick="actualizarAjusteVacacionesCtx('modo','fechas')">📅 Por fechas</button>
      <button type="button" class="${ctx.modo==='numero'?'active':''}" onclick="actualizarAjusteVacacionesCtx('modo','numero')">🔢 Por número</button>
    </div>
    ${ctx.modo === "fechas" ? `
      <div style="display:flex; gap:8px;">
        <div class="field" style="flex:1;">
          <label>Fecha de inicio</label>
          <input type="date" value="${ctx.desde}" onchange="actualizarAjusteVacacionesCtx('desde', this.value)">
        </div>
        <div class="field" style="flex:1;">
          <label>Fecha de fin</label>
          <input type="date" value="${ctx.hasta}" onchange="actualizarAjusteVacacionesCtx('hasta', this.value)">
        </div>
      </div>
      ${rangoInvalido ? `<div class="hint-error">La fecha de fin no puede ser anterior a la de inicio.</div>` : ""}
    ` : `
      <div class="field">
        <label>Cantidad de días</label>
        <input type="text" value="${escapeHtml(ctx.diasManual)}" placeholder="Ej. 5" oninput="actualizarAjusteVacacionesCtx('diasManual', this.value)">
      </div>
    `}
    <div class="sino-toggle" style="margin:10px 0;">
      <button type="button" class="${ctx.signo===-1?'active':''}" onclick="actualizarAjusteVacacionesCtx('signo',-1)">➖ Quitar (ya disfrutadas / excedente)</button>
      <button type="button" class="${ctx.signo===1?'active':''}" onclick="actualizarAjusteVacacionesCtx('signo',1)">➕ Sumar</button>
    </div>
    ${dias ? `<div style="font-weight:700; color:var(--navy-deep); margin-bottom:10px;">Ajuste: ${ajuste > 0 ? "+" : ""}${ajuste} día(s) (${dias} día${dias===1?"":"s"}${ctx.modo==="fechas"?" del rango elegido":""}) → nuevo saldo estimado: ${Math.max(0, ctx.saldoActual + ajuste)} día(s).</div>` : ""}
    <div class="field">
      <label>Motivo (opcional, queda en la bitácora)</label>
      <input type="text" value="${escapeHtml(ctx.motivo)}" oninput="ajusteVacacionesCtx.motivo = this.value;">
    </div>
    <button class="btn primary" style="width:100%;" ${dias ? "" : "disabled"} onclick="confirmarAjusteVacacionesModal()">✅ Aplicar ajuste</button>
  `;
}

async function confirmarAjusteVacacionesModal(){
  const ctx = ajusteVacacionesCtx;
  if (!ctx) return;
  let dias, motivoBase = "";
  if (ctx.modo === "fechas"){
    if (!ctx.desde || !ctx.hasta || ctx.hasta < ctx.desde){ statusMsg("Elige una fecha de inicio y una de fin válidas.", false); return; }
    dias = diasEntreFechasISO(ctx.desde, ctx.hasta) * ctx.signo;
    motivoBase = `Del ${fmtFecha(ctx.desde + "T00:00:00")} al ${fmtFecha(ctx.hasta + "T00:00:00")}`;
  } else {
    const n = parseFloat(String(ctx.diasManual).replace(",", "."));
    if (isNaN(n) || n <= 0){ statusMsg("Escribe una cantidad de días válida.", false); return; }
    dias = n * ctx.signo;
  }
  const motivo = [motivoBase, ctx.motivo.trim()].filter(Boolean).join(" — ");
  const empKey = ctx.empKey, nombreEmp = ctx.nombreEmp;
  try{
    await agregarAjusteVacaciones(empKey, dias, motivo);
    statusMsg(`Ajuste aplicado: ${dias > 0 ? "+" : ""}${dias} día(s) para ${nombreEmp}.`);
    cerrarModalAjusteVacaciones();
    renderDiasLibresVacacionesPanel();
  }catch(e){ statusMsg("No se pudo aplicar el ajuste: " + e.message, false); }
}

function diasEntreFechasISO(desde, hasta){
  const a = new Date(desde + "T00:00:00");
  const b = new Date(hasta + "T00:00:00");
  return Math.round((b - a) / 86400000) + 1;
}

async function listarSolicitudesAusencia(){
  const res = await window.storage.list(SOLICITUD_AUSENCIA_PREFIX, false);
  const keys = (res && res.keys) || [];
  const registros = await Promise.all(keys.map(async k => {
    try{
      const r = await window.storage.get(k, false);
      const v = r && r.value ? JSON.parse(r.value) : {};
      return { key: k, ...v };
    }catch(e){ return null; }
  }));
  return registros.filter(Boolean);
}

// Crea/justifica los días de un rango ISO ("AAAA-MM-DD") en horas_extra: —
// versión de justificarRangoDeFechas que trabaja directo con fechas ISO en
// vez de día/mes(nombre)/año, porque esta solicitud usa <input type=date>
// en vez del selector de mes en español que usan las cartas.
async function justificarRangoISO(empKey, fechaInicioISO, fechaFinISO, tipoDia, origen, camposExtra){
  const cursor = new Date(fechaInicioISO + "T00:00:00");
  const fin = new Date(fechaFinISO + "T00:00:00");
  while (cursor <= fin){
    await crearOJustificarDiaHorasExtra(empKey, isoDeFechaLocal(cursor), tipoDia, origen, camposExtra);
    cursor.setDate(cursor.getDate() + 1);
  }
}

// Crea una solicitud de ausencia (vacaciones / permiso sin goce / ausencia
// médica) — la crea jefatura/líder desde el perfil del colaborador, o
// master/gerente. Valida la anticipación mínima (15 días) y, para citas
// médicas, que venga comprobante adjunto. Queda "pendiente" hasta que
// gerencia o master decidan (sección 4 de la especificación).
async function crearSolicitudAusencia({ empKey, tipo, fechaInicio, fechaFin, comprobanteDataUrl, comprobanteNombre }){
  if (!TIPOS_SOLICITUD_AUSENCIA[tipo]) throw new Error("Tipo de ausencia inválido.");
  if (!empKey) throw new Error("Elegí un empleado.");
  if (!fechaInicio || !fechaFin) throw new Error("Elegí las fechas.");
  if (fechaFin < fechaInicio) throw new Error("La fecha de fin no puede ser anterior a la de inicio.");
  const diasAnticipacion = Math.round((new Date(fechaInicio + "T00:00:00") - new Date(isoDeHoy() + "T00:00:00")) / 86400000);
  if (diasAnticipacion < ANTICIPACION_MINIMA_DIAS_SOLICITUD){
    const faltan = ANTICIPACION_MINIMA_DIAS_SOLICITUD - diasAnticipacion;
    throw new Error(`Esta solicitud necesita al menos ${ANTICIPACION_MINIMA_DIAS_SOLICITUD} días de anticipación (faltan ${faltan} día(s) para cumplirlo).`);
  }
  if (TIPOS_SOLICITUD_AUSENCIA[tipo].requiereComprobante && !comprobanteDataUrl){
    throw new Error("Este tipo de ausencia necesita un comprobante adjunto.");
  }
  const dias = diasEntreFechasISO(fechaInicio, fechaFin);
  const id = `${fechaInicio}-${Date.now()}`;
  const key = SOLICITUD_AUSENCIA_PREFIX + empKey + ":" + id;
  const value = {
    EMPLEADO_KEY: empKey,
    TIPO: tipo,
    FECHA_INICIO: fechaInicio,
    FECHA_FIN: fechaFin,
    DIAS: dias,
    COMPROBANTE_DATA_URL: comprobanteDataUrl || null,
    COMPROBANTE_NOMBRE: comprobanteNombre || null,
    SOLICITADO_POR: (window.sdgApi && window.sdgApi.sesionActual() && window.sdgApi.sesionActual().email) || "",
    FECHA_SOLICITUD: new Date().toISOString(),
    ESTADO: "pendiente",
  };
  await window.storage.set(key, JSON.stringify(value), false);
  return key;
}

// Asignación directa — exclusiva de gerencia/master. A diferencia de una
// solicitud (la crea jefatura y queda "pendiente" hasta que gerencia/master
// decida), esto lo crea gerencia/master directamente YA aprobado: no pasa
// por la cola de pendientes ni exige los 15 días de anticipación (esa regla
// es para la solicitud que pide jefatura, no para quien ya tiene la
// autoridad final de aprobarla).
async function asignarAusenciaDirecta({ empKey, tipo, fechaInicio, fechaFin, comprobanteDataUrl, comprobanteNombre }){
  if (!TIPOS_SOLICITUD_AUSENCIA[tipo]) throw new Error("Tipo de ausencia inválido.");
  if (!empKey) throw new Error("Elegí un empleado.");
  if (!fechaInicio || !fechaFin) throw new Error("Elegí las fechas.");
  if (fechaFin < fechaInicio) throw new Error("La fecha de fin no puede ser anterior a la de inicio.");
  if (TIPOS_SOLICITUD_AUSENCIA[tipo].requiereComprobante && !comprobanteDataUrl){
    throw new Error("Este tipo de ausencia necesita un comprobante adjunto.");
  }
  const dias = diasEntreFechasISO(fechaInicio, fechaFin);
  const id = `${fechaInicio}-${Date.now()}`;
  const key = SOLICITUD_AUSENCIA_PREFIX + empKey + ":" + id;
  const email = (window.sdgApi && window.sdgApi.sesionActual() && window.sdgApi.sesionActual().email) || "";
  const value = {
    EMPLEADO_KEY: empKey,
    TIPO: tipo,
    FECHA_INICIO: fechaInicio,
    FECHA_FIN: fechaFin,
    DIAS: dias,
    COMPROBANTE_DATA_URL: comprobanteDataUrl || null,
    COMPROBANTE_NOMBRE: comprobanteNombre || null,
    SOLICITADO_POR: email,
    FECHA_SOLICITUD: new Date().toISOString(),
    ESTADO: "aprobada",
    APROBADO_POR: email,
    FECHA_DECISION: new Date().toISOString(),
    ORIGEN: "asignacion_directa",
  };
  await window.storage.set(key, JSON.stringify(value), false);
  await justificarRangoISO(empKey, fechaInicio, fechaFin, tipo, "asignacion_directa", { SOLICITUD_KEY: key });
  return key;
}

// Aprobación — exclusiva de gerencia/master (el servidor lo exige para
// jefatura). Al aprobar se justifican los días en horas_extra: para que
// cuenten en el reporte de planilla. Para SCP Corcovado Wilderness Lodge la
// única regla especial del reglamento interno que aplica es el día de
// cumpleaños (ver otorgarDiaCumpleanos) — día de viaje y día de entrada NO
// aplican acá, así que no se generan.
async function aprobarSolicitudAusencia(key){
  try{
    const r = await window.storage.get(key, false);
    const v = r && r.value ? JSON.parse(r.value) : null;
    if (!v) return;
    v.ESTADO = "aprobada";
    v.APROBADO_POR = (window.sdgApi && window.sdgApi.sesionActual() && window.sdgApi.sesionActual().email) || "";
    v.FECHA_DECISION = new Date().toISOString();
    await window.storage.set(key, JSON.stringify(v), false);

    await justificarRangoISO(v.EMPLEADO_KEY, v.FECHA_INICIO, v.FECHA_FIN, v.TIPO, "solicitud_ausencia", { SOLICITUD_KEY: key });

    statusMsg("Solicitud aprobada.");
    if (typeof renderDiasLibresVacacionesPanel === "function") renderDiasLibresVacacionesPanel();
  }catch(e){ statusMsg("No se pudo aprobar: " + e.message, false); }
}

async function rechazarSolicitudAusencia(key){
  const motivo = prompt("Motivo del rechazo (opcional):", "");
  if (motivo === null) return;
  try{
    const r = await window.storage.get(key, false);
    const v = r && r.value ? JSON.parse(r.value) : null;
    if (!v) return;
    v.ESTADO = "rechazada";
    v.APROBADO_POR = (window.sdgApi && window.sdgApi.sesionActual() && window.sdgApi.sesionActual().email) || "";
    v.FECHA_DECISION = new Date().toISOString();
    v.MOTIVO_RECHAZO = motivo.trim();
    await window.storage.set(key, JSON.stringify(v), false);
    statusMsg("Solicitud rechazada.");
    if (typeof renderDiasLibresVacacionesPanel === "function") renderDiasLibresVacacionesPanel();
  }catch(e){ statusMsg("No se pudo rechazar: " + e.message, false); }
}

async function cancelarSolicitudAusencia(key){
  if (!confirm("¿Cancelar esta solicitud pendiente?")) return;
  try{
    await window.storage.delete(key, false);
    statusMsg("Solicitud cancelada.");
    if (typeof renderDiasLibresVacacionesPanel === "function") renderDiasLibresVacacionesPanel();
  }catch(e){ statusMsg("No se pudo cancelar: " + e.message, false); }
}

// ---------- Días Libres y Vacaciones: cumpleaños, coincidencias, UI ----------

function departamentoDeEmpleadoGenerico(emp, puestosPorKey){
  if (!emp || !emp.PUESTO_KEY) return "Sin departamento";
  const p = puestosPorKey[emp.PUESTO_KEY];
  return (p && p.DEPARTAMENTO_MINISTERIO) || "Sin departamento";
}

// Próxima ocurrencia del cumpleaños (este año, o el que viene si ya pasó),
// dentro de una ventana de días — para la alerta de la sección 5. Un día de
// cumpleaños es "todo o nada" por año: no se fracciona ni se acumula si no
// se otorga (ver otorgadoEsteAnio).
function proximoCumpleanosEn(fechaNacStr, hoy, ventanaDias){
  const nacimiento = parsearFechaDDMMYYYY(fechaNacStr);
  if (!nacimiento) return null;
  let cumple = new Date(hoy.getFullYear(), nacimiento.getMonth(), nacimiento.getDate());
  if (cumple < new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate())){
    cumple = new Date(hoy.getFullYear() + 1, nacimiento.getMonth(), nacimiento.getDate());
  }
  const diasFaltan = Math.round((cumple - hoy) / 86400000);
  return diasFaltan <= ventanaDias ? { fecha: cumple, diasFaltan } : null;
}

function otorgadoEsteAnio(emp, anio){
  return !!(emp && emp.CUMPLEANOS_OTORGADO_ANIOS && emp.CUMPLEANOS_OTORGADO_ANIOS[String(anio)]);
}

// El botón "Otorgar día" sugería la fecha calculada del próximo cumpleaños
// sin dar oportunidad de corregirla (ej. si el día libre se toma otro día
// distinto al cumpleaños exacto, como el viernes anterior si cae en fin de
// semana). Este modal muestra un calendario con esa fecha ya sugerida —
// basta con confirmar en el caso normal, pero se puede cambiar antes de
// otorgar.
let otorgarCumpleanosCtx = null;

function abrirModalOtorgarCumpleanos(empKey, nombreEmp, fechaSugeridaISO){
  otorgarCumpleanosCtx = { empKey, nombreEmp, fecha: fechaSugeridaISO };
  renderModalOtorgarCumpleanos();
  document.getElementById("modal-otorgar-cumpleanos").classList.add("open");
}

function cerrarModalOtorgarCumpleanos(){
  const modal = document.getElementById("modal-otorgar-cumpleanos");
  if (modal) modal.classList.remove("open");
  otorgarCumpleanosCtx = null;
}

function renderModalOtorgarCumpleanos(){
  const ctx = otorgarCumpleanosCtx;
  const body = document.getElementById("modal-otorgar-cumpleanos-body");
  if (!ctx || !body) return;
  body.innerHTML = `
    <div style="font-size:12.5px; color:var(--ink-soft); margin-bottom:10px;">Elige el día que se le otorga a <b>${escapeHtml(ctx.nombreEmp)}</b> — ya viene con la fecha de su cumpleaños, ajústala si el día libre se toma otro día.</div>
    <div class="field">
      <label>Fecha a otorgar</label>
      <input type="date" value="${ctx.fecha}" onchange="otorgarCumpleanosCtx.fecha = this.value;">
    </div>
    <button class="btn primary" style="width:100%; margin-top:6px;" onclick="confirmarOtorgarCumpleanos()">🎁 Otorgar día</button>
  `;
}

async function confirmarOtorgarCumpleanos(){
  const ctx = otorgarCumpleanosCtx;
  if (!ctx) return;
  if (!ctx.fecha){ statusMsg("Elige una fecha.", false); return; }
  const empKey = ctx.empKey, fecha = ctx.fecha;
  cerrarModalOtorgarCumpleanos();
  await otorgarDiaCumpleanos(empKey, fecha);
}

async function otorgarDiaCumpleanos(empKey, fechaISO){
  try{
    const fullKey = CATALOGS.empleados.prefix + empKey;
    const res = await window.storage.get(fullKey, false);
    if (!res || !res.value) return;
    const emp = JSON.parse(res.value);
    const anio = fechaISO.slice(0,4);
    if (!emp.CUMPLEANOS_OTORGADO_ANIOS) emp.CUMPLEANOS_OTORGADO_ANIOS = {};
    emp.CUMPLEANOS_OTORGADO_ANIOS[anio] = true;
    await window.storage.set(fullKey, JSON.stringify(emp), false);
    await crearOJustificarDiaHorasExtra(empKey, fechaISO, "cumpleanos", "cumpleanos_otorgado", {});
    statusMsg("Día de cumpleaños otorgado.");
    renderDiasLibresVacacionesPanel();
    // También se puede otorgar desde el expediente (Perfil) — si es ese
    // empleado el que está abierto ahí, se refresca también, no solo el
    // panel de Días Libres y Vacaciones.
    if (typeof perfilActualKey !== "undefined" && perfilActualKey === empKey && typeof renderPerfilEmpleado === "function"){
      renderPerfilEmpleado();
    }
  }catch(e){ statusMsg("No se pudo otorgar: " + e.message, false); }
}

// Dos o más colaboradores del MISMO departamento con vacaciones o permiso
// sin goce programados el mismo día — no bloquea nada, solo alerta (sección
// 6.5). Solo mira solicitudes aprobadas o pendientes (una rechazada/cancelada
// ya no es un conflicto real).
function detectarCoincidencias(solicitudes, empleadosPorKey, departamentoDeEmpleado){
  const porDeptoFecha = {};
  solicitudes
    .filter(s => (s.ESTADO === "aprobada" || s.ESTADO === "pendiente") && (s.TIPO === "vacaciones" || s.TIPO === "dia_libre" || s.TIPO === "permiso_sin_goce"))
    .forEach(s => {
      const emp = empleadosPorKey[s.EMPLEADO_KEY];
      const depto = departamentoDeEmpleado(emp);
      const cursor = new Date(s.FECHA_INICIO + "T00:00:00");
      const fin = new Date(s.FECHA_FIN + "T00:00:00");
      while (cursor <= fin){
        const clave = depto + "|" + isoDeFechaLocal(cursor);
        (porDeptoFecha[clave] = porDeptoFecha[clave] || []).push(s.EMPLEADO_KEY);
        cursor.setDate(cursor.getDate() + 1);
      }
    });
  const coincidencias = [];
  Object.keys(porDeptoFecha).forEach(clave => {
    const empleadosUnicos = [...new Set(porDeptoFecha[clave])];
    if (empleadosUnicos.length >= 2){
      const [depto, fecha] = clave.split("|");
      coincidencias.push({ depto, fecha, empleados: empleadosUnicos });
    }
  });
  coincidencias.sort((a,b) => a.fecha.localeCompare(b.fecha));
  return coincidencias;
}

const COINCIDENCIA_PREFIX = "coincidencia_confirmada:";

// La solicitud NO se bloquea automáticamente: jefatura y gerencia/master
// confirman cada quien su lado, y solo cuando ambos confirmaron se
// considera aceptada (sección 6.5).
async function confirmarCoincidencia(depto, fecha, quien){
  const key = COINCIDENCIA_PREFIX + depto + ":" + fecha;
  try{
    const r = await window.storage.get(key, false);
    const v = r && r.value ? JSON.parse(r.value) : { CONFIRMADO_JEFATURA: false, CONFIRMADO_GERENCIA: false };
    if (quien === "jefatura") v.CONFIRMADO_JEFATURA = true;
    if (quien === "gerencia") v.CONFIRMADO_GERENCIA = true;
    await window.storage.set(key, JSON.stringify(v), false);
    statusMsg("Confirmación registrada.");
    renderDiasLibresVacacionesPanel();
  }catch(e){ statusMsg("No se pudo confirmar: " + e.message, false); }
}

async function obtenerConfirmacionesCoincidencia(){
  const res = await window.storage.list(COINCIDENCIA_PREFIX, false);
  const keys = (res && res.keys) || [];
  const mapa = {};
  await Promise.all(keys.map(async k => {
    try{
      const r = await window.storage.get(k, false);
      const v = r && r.value ? JSON.parse(r.value) : null;
      if (v) mapa[k.replace(COINCIDENCIA_PREFIX, "")] = v;
    }catch(e){ /* se ignora ese registro suelto */ }
  }));
  return mapa;
}

let diasLibresFiltroDepto = "todos";
let diasLibresMesCalendario = null; // "AAAA-MM" — se fija al mes actual la primera vez que se renderiza

async function renderDiasLibresVacacionesPanel(){
  const panel = document.getElementById("diaslibresvacaciones-panel");
  if (!panel) return;
  panel.innerHTML = `<div class="empty-state">Cargando…</div>`;
  try{
    const rolActual = window.sdgApi ? window.sdgApi.rol() : null;
    const esJefatura = rolActual === "jefatura";
    const puedeAprobar = !!(window.sdgApi && window.sdgApi.puedeEditar()); // master/gerente: aprueban/rechazan/asignan directo
    const sesion = window.sdgApi && window.sdgApi.sesionActual();
    const deptoJefatura = esJefatura && sesion ? (sesion.puesto || "") : null;

    const [empleados, solicitudes, registrosHorasExtra] = await Promise.all([
      cargarEmpleadosDB(),
      listarSolicitudesAusencia(),
      listarRegistrosHorasExtra(),
    ]);
    const resPuestos = await window.storage.list(CATALOGS.puestos.prefix, false);
    const puestoKeys = (resPuestos && resPuestos.keys) || [];
    const puestos = await Promise.all(puestoKeys.map(async k => {
      const r = await window.storage.get(k, false);
      const v = r && r.value ? JSON.parse(r.value) : {};
      return { key: k.replace(CATALOGS.puestos.prefix, ""), ...v };
    }));
    const puestosPorKey = {};
    puestos.forEach(p => { puestosPorKey[p.key] = p; });
    const empleadosPorKey = {};
    empleados.forEach(e => { empleadosPorKey[e.key] = e; });
    const departamentoDeEmpleado = emp => departamentoDeEmpleadoGenerico(emp, puestosPorKey);

    if (!diasLibresMesCalendario){
      const hoy0 = new Date();
      diasLibresMesCalendario = `${hoy0.getFullYear()}-${String(hoy0.getMonth()+1).padStart(2,"0")}`;
    }

    // Ámbito por rol (sección 6.2): jefatura fija a su propio departamento;
    // master/gerente eligen "todos" o uno específico.
    const deptoActivo = deptoJefatura || (diasLibresFiltroDepto === "todos" ? null : diasLibresFiltroDepto);
    const empleadosVisibles = empleados.filter(e => !e.ARCHIVADO && (!deptoActivo || departamentoDeEmpleado(e) === deptoActivo));
    const empleadosVisiblesKeys = new Set(empleadosVisibles.map(e => e.key));
    const solicitudesVisibles = solicitudes.filter(s => empleadosVisiblesKeys.has(s.EMPLEADO_KEY));

    let html = `<div style="margin-bottom:14px;">
      <div style="font-size:18px; font-weight:800; color:var(--navy-deep);">🏖️ Días Libres y Vacaciones</div>
      <div style="font-size:12px; color:var(--ink-soft);">Saldo acumulado (${ACUMULACION_MENSUAL_VACACIONES} día${ACUMULACION_MENSUAL_VACACIONES===1?"":"s"}/mes — primer año por aniversario de ingreso, luego por el ciclo fijo 1° dic al 30 nov —, tope interno de ${TOPE_SALDO_VACACIONES}), solicitudes con aprobación de gerencia/master, y calendario del equipo.</div>
    </div>`;

    if (!esJefatura){
      html += `<div style="margin-bottom:12px;">
        <select onchange="diasLibresFiltroDepto=this.value; renderDiasLibresVacacionesPanel();">
          <option value="todos"${diasLibresFiltroDepto==="todos"?" selected":""}>Todos los departamentos</option>
          ${DEPARTAMENTOS_MINISTERIO.map(d => `<option value="${escapeHtml(d)}"${diasLibresFiltroDepto===d?" selected":""}>${escapeHtml(d)}</option>`).join("")}
        </select>
      </div>`;
    }

    // El día de cumpleaños es una regla exclusiva de SCP Corcovado Wilderness
    // Lodge. Las demás propiedades (Oxygen, Ojochal, Amarena) no la manejan
    // — su descanso es 1 día libre por semana o un bloque de 4 días, sin
    // días pagados aparte.
    if (currentPropiedadId === "corcovado"){
      html += renderSeccionCumpleanos(empleadosVisibles, puedeAprobar);
    }

    const confirmaciones = await obtenerConfirmacionesCoincidencia();
    html += renderSeccionCoincidencias(solicitudesVisibles, empleadosPorKey, departamentoDeEmpleado, confirmaciones, esJefatura, puedeAprobar);

    // Quién pide y quién asigna son roles distintos: jefatura PIDE (queda
    // pendiente hasta que gerencia/master decida) — gerencia/master no
    // necesita pedirse nada a sí mismo, así que en vez del formulario de
    // solicitud tiene uno propio de asignación directa (ver
    // asignarAusenciaDirecta), que ya queda aprobado de una vez.
    if (esJefatura) html += renderFormularioSolicitud(empleadosVisibles);
    if (puedeAprobar) html += renderFormularioAsignacionDirecta(empleadosVisibles);

    html += renderListaSolicitudesPendientes(solicitudesVisibles, empleadosPorKey, departamentoDeEmpleado, puedeAprobar, esJefatura);

    html += renderCalendarioMensual(empleadosVisibles, solicitudes, registrosHorasExtra, diasLibresMesCalendario);

    html += renderSeccionReportesAusencias();

    // La tabla de saldos es una fila por empleado (fácilmente 40-50 filas
    // entre varias propiedades) — va al final, después de todo lo que
    // requiere acción (solicitudes, calendario, reportes), no primero.
    html += renderTablaSaldos(empleadosVisibles, solicitudes, registrosHorasExtra, new Date());

    panel.innerHTML = html;
  }catch(e){
    panel.innerHTML = `<div class="empty-state">No se pudo cargar el módulo: ${escapeHtml(e.message || "")}</div>`;
  }
}

function renderSeccionCumpleanos(empleados, puedeOtorgar){
  const hoy = new Date();
  const proximos = empleados
    .map(e => {
      const prox = proximoCumpleanosEn(e.FECHA_NACIMIENTO_EMP, hoy, 30);
      if (!prox) return null;
      if (otorgadoEsteAnio(e, prox.fecha.getFullYear())) return null;
      return { emp: e, ...prox };
    })
    .filter(Boolean)
    .sort((a,b) => a.diasFaltan - b.diasFaltan);
  if (!proximos.length) return "";
  return `<div class="section-card" style="margin-bottom:14px; border-color:var(--gold);"><div class="section-body">
    <div style="font-weight:700; color:var(--navy-deep); margin-bottom:8px;">🎂 Cumpleaños próximos — 1 día pagado, se pierde si no se otorga en el año</div>
    ${proximos.map(p => `
      <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:5px 0; border-bottom:1px solid var(--paper-line);">
        <div style="font-size:12.5px;"><b>${escapeHtml(nombreCompletoEmpleado(p.emp))}</b> — ${fmtFechaDesdeDate(p.fecha)} (${p.diasFaltan === 0 ? "hoy" : `en ${p.diasFaltan} día(s)`})</div>
        ${puedeOtorgar ? `<button class="btn primary" style="padding:5px 10px; font-size:11px;" onclick="abrirModalOtorgarCumpleanos('${p.emp.key}', '${nombreCompletoEmpleado(p.emp).replace(/'/g,"\\'")}', '${isoDeFechaLocal(p.fecha)}')">🎁 Otorgar día</button>` : `<span class="meta">Pendiente — lo otorga gerencia/master</span>`}
      </div>`).join("")}
  </div></div>`;
}

function renderSeccionCoincidencias(solicitudes, empleadosPorKey, departamentoDeEmpleado, confirmaciones, esJefatura, puedeAprobar){
  const coincidencias = detectarCoincidencias(solicitudes, empleadosPorKey, departamentoDeEmpleado);
  const pendientes = coincidencias.filter(c => {
    const conf = confirmaciones[c.depto + ":" + c.fecha];
    return !(conf && conf.CONFIRMADO_JEFATURA && conf.CONFIRMADO_GERENCIA);
  });
  if (!pendientes.length) return "";
  return `<div class="section-card" style="margin-bottom:14px; border-color:#D9A54A;"><div class="section-body">
    <div style="font-weight:700; color:var(--navy-deep); margin-bottom:8px;">⚠️ Coincidencias de días libres en el mismo departamento</div>
    <p style="font-size:12px; color:var(--ink-soft); margin:0 0 8px;">No se bloquea automáticamente — jefatura y gerencia/master deben confirmar explícitamente que aceptan que salgan libres al mismo tiempo.</p>
    ${pendientes.map(c => {
      const conf = confirmaciones[c.depto + ":" + c.fecha] || {};
      const nombres = c.empleados.map(k => (empleadosPorKey[k] && nombreCompletoEmpleado(empleadosPorKey[k])) || k).join(", ");
      const deptoEsc = c.depto.replace(/'/g,"\\'");
      return `<div style="padding:6px 0; border-bottom:1px solid var(--paper-line); font-size:12.5px;">
        <div><b>${escapeHtml(c.depto)}</b> — ${fmtFechaSimple(c.fecha)}: ${escapeHtml(nombres)}</div>
        <div style="margin-top:4px; display:flex; gap:8px; flex-wrap:wrap;">
          ${conf.CONFIRMADO_JEFATURA ? `<span class="meta">✅ Jefatura confirmó</span>` : ((esJefatura || puedeAprobar) ? `<button class="btn" style="padding:4px 9px; font-size:10.5px;" onclick="confirmarCoincidencia('${deptoEsc}', '${c.fecha}', 'jefatura')">Confirmar (jefatura)</button>` : "")}
          ${conf.CONFIRMADO_GERENCIA ? `<span class="meta">✅ Gerencia/master confirmó</span>` : (puedeAprobar ? `<button class="btn" style="padding:4px 9px; font-size:10.5px;" onclick="confirmarCoincidencia('${deptoEsc}', '${c.fecha}', 'gerencia')">Confirmar (gerencia/master)</button>` : "")}
        </div>
      </div>`;
    }).join("")}
  </div></div>`;
}

